    try qkvDecParityCase(8, 2, 128, 4, 37, true);
}

test "qkv decode kernel parity: multi-block split-KV merge (T_k > BLOCK)" {
    // g=4/DK=64 → BLOCK 512, so 700+1 rows exercises the two-block partial
