test "batchedExpertDecodePolicy: stock gather is the default on EVERY arch" {
    // History, and why the laguna opt-in was retired.
    //
    // The batchedExpertMm decode path (take + batched quantized_matmul) and
    // then `gatherQmv` both exist to dodge our self-built libmlx's decode
    // `gather_qmm`, whose cost is O(EXPERT BANK SIZE) rather than O(work).
    // Laguna opted in by default on a measured 17→48 tok/s.
    //
    // That measurement was taken on a forward pass inflated ~3x by the YaRN
    // mscale f32 promotion. With the promotion fixed the expert math is a much
    // larger share of a much cheaper token, the O(bank) addressing term is a
    // correspondingly smaller one, and MLX's better-tuned `gather_qmv_fast`
    // tile wins — the SAME reasoning that already explained why gemma4-26B-A4B
    // loses with gatherQmv. Re-measured on the fixed tree, alternating boots,
    // 512-token window, serial:
    //
    //   Laguna XS  gatherQmv 13.296 ms/tok   stock 13.113   stock +1.4%
    //   Laguna S   gatherQmv 17.02  ms/tok   stock 15.45    stock +9.2%
    //   (batched take+qmm on XS: 14.839 — worst of the three)
    //
    // Both models, every round, no overlap. So there is no arch left whose
    // default should be anything but stock gather. Both kernels stay reachable
    // by env for A/B — the finding is about the DEFAULT, and the next arch
    // with a genuinely bank-dominated decode can be measured back in.
    try testing.expect(!batchedExpertDecodePolicy("laguna", false, false));
    try testing.expect(!batchedExpertDecodePolicy("gemma4_text", false, false));
    try testing.expect(!batchedExpertDecodePolicy("qwen3_5_moe", false, false));
    try testing.expect(!batchedExpertDecodePolicy("hy_v3", false, false));
    // MLX_SERVE_MOE_BATCHED_DECODE forces it on for any arch (experimentation A/B).
    try testing.expect(batchedExpertDecodePolicy("gemma4_text", false, true));
    try testing.expect(batchedExpertDecodePolicy("laguna", false, true));
    // MLX_SERVE_MOE_GATHER_DECODE is the hard override: still beats the force.
    try testing.expect(!batchedExpertDecodePolicy("laguna", true, false));
    try testing.expect(!batchedExpertDecodePolicy("gemma4_text", true, true));
}

test "moeRoutingChain produces top-K indices and renormalized softmax weights" {
    const s = mlx.gpuStream();

    // Two rows of router logits over 6 experts. Top-2 of each row is unambiguous:
    //   row 0: experts {0, 3} (logits 10 and 5)
    //   row 1: experts {1, 4} (logits 10 and 5)
    const n_rows: c_int = 2;
    const n_exp: c_int = 6;
    const k: c_int = 2;
    const data = [_]f32{
        10.0, 0.0,  0.0, 5.0, 0.0, 0.0,
        0.0,  10.0, 0.0, 0.0, 5.0, 0.0,
    };
    const shape = [_]c_int{ n_rows, n_exp };
    const logits = mlx.mlx_array_new_data(&data, &shape, 2, .float32);
    defer _ = mlx.mlx_array_free(logits);

    const routed = try moeRoutingChain(logits, k, s);
    defer _ = mlx.mlx_array_free(routed.inds);
    defer _ = mlx.mlx_array_free(routed.norm_scores);

    // Shape check (cheap, no data read needed).
    {
        const inds_shape = mlx.getShape(routed.inds);
        try testing.expectEqual(@as(usize, 2), inds_shape.len);
        try testing.expectEqual(n_rows, inds_shape[0]);
        try testing.expectEqual(k, inds_shape[1]);
        const sc_shape = mlx.getShape(routed.norm_scores);
        try testing.expectEqual(@as(usize, 2), sc_shape.len);
        try testing.expectEqual(n_rows, sc_shape[0]);
        try testing.expectEqual(k, sc_shape[1]);
    }

    // To verify top-K correctness without reading non-contiguous slice memory
    // directly, gather the original logits at the selected indices: gathered[i,j]
    // == logits[i, inds[i,j]]. Then sum across K — for our fixture, the top-2
    // logits in each row are {10, 5}, so the per-row sum must be 15.
    var gathered = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gathered);
    try mlx.check(mlx.mlx_take_along_axis(&gathered, logits, routed.inds, -1, s));
    var gathered_sum = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gathered_sum);
    try mlx.check(mlx.mlx_sum_axis(&gathered_sum, gathered, -1, false, s));

    // norm_scores must sum to 1 along K (verifies the renormalize step).
    var scores_sum = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(scores_sum);
    try mlx.check(mlx.mlx_sum_axis(&scores_sum, routed.norm_scores, -1, false, s));

    {
        const ev = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(ev);
        _ = mlx.mlx_vector_array_append_value(ev, gathered_sum);
        _ = mlx.mlx_vector_array_append_value(ev, scores_sum);
        try mlx.check(mlx.mlx_eval(ev));
    }

    // gathered_sum and scores_sum are 1D outputs of sum_axis (contiguous).
    const gs = mlx.mlx_array_data_float32(gathered_sum) orelse return error.InvalidDtype;
    const ss = mlx.mlx_array_data_float32(scores_sum) orelse return error.InvalidDtype;
    const tol: f32 = 1e-3;
    try testing.expect(@abs(gs[0] - 15.0) < tol);
    try testing.expect(@abs(gs[1] - 15.0) < tol);
    try testing.expect(@abs(ss[0] - 1.0) < tol);
    try testing.expect(@abs(ss[1] - 1.0) < tol);
}

test "hy3RoutingChain selects on biased scores but weights by original sigmoid scores" {
    const s = mlx.gpuStream();

    // 1 row over 6 experts, k=2. sigmoid(logits):
    //   [0.8808, 0.5, 0.1192, 0.7311, 0.2689, 0.6225]
    // With NO bias the top-2 would be {0 (0.8808), 3 (0.7311)}. The expert bias
    // +0.5 on expert 1 lifts it to 1.0, so selection must pick {1, 0} — but the
    // WEIGHTS must come from the ORIGINAL sigmoid scores {0.5, 0.8808}
    // (sum 1.3808), renormalized to 1 then scaled by router_scaling_factor.
    const logits_data = [_]f32{ 2.0, 0.0, -2.0, 1.0, -1.0, 0.5 };
    const shape = [_]c_int{ 1, 6 };
    const logits = mlx.mlx_array_new_data(&logits_data, &shape, 2, .float32);
    defer _ = mlx.mlx_array_free(logits);

    const bias_data = [_]f32{ 0.0, 0.5, 0.0, 0.0, 0.0, 0.0 };
    const bias_shape = [_]c_int{6};
    const bias = mlx.mlx_array_new_data(&bias_data, &bias_shape, 1, .float32);
    defer _ = mlx.mlx_array_free(bias);

    const scale: f32 = 2.0;
    const routed = try hy3RoutingChain(logits, bias, 2, true, scale, s);
    defer _ = mlx.mlx_array_free(routed.inds);
    defer _ = mlx.mlx_array_free(routed.norm_scores);

    // Gather the ORIGINAL sigmoid scores at the selected indices. If selection
    // ignored the bias the gathered sum would be 0.8808+0.7311 = 1.6119; with
    // bias-driven selection it must be 0.5+0.8808 = 1.3808.
    var sig = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(sig);
    try mlx.check(mlx.mlx_sigmoid(&sig, logits, s));
    var gathered = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gathered);
    try mlx.check(mlx.mlx_take_along_axis(&gathered, sig, routed.inds, -1, s));
    var gathered_sum = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gathered_sum);
    try mlx.check(mlx.mlx_sum_axis(&gathered_sum, gathered, -1, false, s));

    // Renorm + scale: scores sum to exactly router_scaling_factor.
    var scores_f32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(scores_f32);
    try mlx.check(mlx.mlx_astype(&scores_f32, routed.norm_scores, .float32, s));
    var scores_sum = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(scores_sum);
    try mlx.check(mlx.mlx_sum_axis(&scores_sum, scores_f32, -1, false, s));

    {
        const ev = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(ev);
        _ = mlx.mlx_vector_array_append_value(ev, gathered_sum);
        _ = mlx.mlx_vector_array_append_value(ev, scores_sum);
        try mlx.check(mlx.mlx_eval(ev));
    }

    const gs = mlx.mlx_array_data_float32(gathered_sum) orelse return error.InvalidDtype;
    const ss = mlx.mlx_array_data_float32(scores_sum) orelse return error.InvalidDtype;
    // norm_scores are bf16 (cast for the expert-combine multiply) → ~0.4% rel.
    try testing.expect(@abs(gs[0] - 1.3808) < 1e-3);
    try testing.expect(@abs(ss[0] - scale) < 0.02);

    // Per-element weights pin "weighted by ORIGINAL scores": {0.5, 0.8808}
    // renormed ×2 → {0.7242, 1.2758} (any order). Had the chain weighted by
    // the BIASED scores {1.0, 0.8808} the pair would be {1.0634, 0.9366} —
    // same sum, different elements, so the sum check alone can't see it.
    try mlx.check(mlx.mlx_array_eval(scores_f32));
    const sv = mlx.mlx_array_data_float32(scores_f32) orelse return error.InvalidDtype;
    const lo = @min(sv[0], sv[1]);
    const hi = @max(sv[0], sv[1]);
    try testing.expect(@abs(lo - 0.7242) < 0.02);
    try testing.expect(@abs(hi - 1.2758) < 0.02);
}

test "hy3RoutingChain route_norm=false keeps raw sigmoid weights (scaled only)" {
    const s = mlx.gpuStream();

    const logits_data = [_]f32{ 2.0, 0.0, -2.0, 1.0, -1.0, 0.5 };
    const shape = [_]c_int{ 1, 6 };
    const logits = mlx.mlx_array_new_data(&logits_data, &shape, 2, .float32);
    defer _ = mlx.mlx_array_free(logits);

    // Zero bias: selection = top-2 of raw sigmoid = {0.8808, 0.7311}.
    const bias_data: [6]f32 = @splat(0.0);
    const bias_shape = [_]c_int{6};
    const bias = mlx.mlx_array_new_data(&bias_data, &bias_shape, 1, .float32);
    defer _ = mlx.mlx_array_free(bias);

    const routed = try hy3RoutingChain(logits, bias, 2, false, 2.0, s);
    defer _ = mlx.mlx_array_free(routed.inds);
    defer _ = mlx.mlx_array_free(routed.norm_scores);

    var scores_f32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(scores_f32);
    try mlx.check(mlx.mlx_astype(&scores_f32, routed.norm_scores, .float32, s));
    var scores_sum = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(scores_sum);
    try mlx.check(mlx.mlx_sum_axis(&scores_sum, scores_f32, -1, false, s));
    try mlx.check(mlx.mlx_array_eval(scores_sum));

    const ss = mlx.mlx_array_data_float32(scores_sum) orelse return error.InvalidDtype;
    // (0.880797 + 0.731059) × 2.0 = 3.2237 — un-normalized, scaled.
    try testing.expect(@abs(ss[0] - 3.2237) < 0.02);
}

test "computeYarnFreqs matches HF _compute_yarn_parameters (Laguna full-attn rope)" {
    // Golden values from the reference YaRN math (tests/dump_laguna_fixtures.py
    // and the pure-Python cross-check): head_dim 128, partial 0.5 → dim 64 →
    // 32 freqs; base 5e5, factor 32, beta_fast 32, beta_slow 1, orig_max 8192.
    // low/high correction dims truncate to 9/18.
    var freqs: [32]f64 = undefined;
    computeYarnFreqs(&freqs, 128, 0.5, 500000.0, 32.0, 32.0, 1.0, 8192);
    // Spot-check the denominator array mlx_fast_rope consumes (angle = pos/freqs).
    const golden = [_]struct { idx: usize, val: f64 }{
        .{ .idx = 0, .val = 1.000000000e+00 },
        .{ .idx = 1, .val = 1.506929076e+00 },
        .{ .idx = 2, .val = 2.270835240e+00 },
        .{ .idx = 7, .val = 1.764613870e+01 },
        .{ .idx = 15, .val = 1.324904288e+03 },
        .{ .idx = 16, .val = 2.868264127e+03 },
        .{ .idx = 23, .val = 3.992865387e+05 },
        .{ .idx = 31, .val = 1.061761980e+07 },
    };
    for (golden) |g| {
        try testing.expectApproxEqRel(g.val, freqs[g.idx], 1e-7);
    }
    // Below the low correction dim (9): pure extrapolation → freqs = base^(2i/64).
    try testing.expectApproxEqRel(std.math.pow(f64, 500000.0, 0.0), freqs[0], 1e-9);
    // Above the high correction dim (18): pure interpolation → freqs = factor·base^(2i/64).
    try testing.expectApproxEqRel(32.0 * std.math.pow(f64, 500000.0, @as(f64, 2 * 31) / 64.0), freqs[31], 1e-6);
}

test "laguna yarn parity vs modeling_laguna.py (LAGUNA_FIXTURES)" {
    // Env-gated cos/value oracle: compare computeYarnFreqs against the
    // full-attention rotary frequencies dumped from the reference
    // modeling_laguna.py (tests/dump_laguna_fixtures.py, CPU fp32). Dormant in
    // normal CI; run with LAGUNA_FIXTURES=/tmp/laguna_fixtures.json. The
    // fixture's `yarn.freqs` = 1/inv_freq (the mlx_fast_rope denominator).
    const path_z = std.c.getenv("LAGUNA_FIXTURES") orelse return error.SkipZigTest;
    const path = std.mem.span(path_z);
    if (path.len == 0) return error.SkipZigTest;
    const io = std.Io.Threaded.global_single_threaded.io();
    const file = try std.Io.Dir.openFileAbsolute(io, path, .{});
    defer file.close(io);
    var read_buf: [4096]u8 = undefined;
    var reader_state = file.reader(io, &read_buf);
    const data = try reader_state.interface.allocRemaining(testing.allocator, .limited(1 << 20));
    defer testing.allocator.free(data);
    var parsed = try std.json.parseFromSlice(std.json.Value, testing.allocator, data, .{});
    defer parsed.deinit();
    const yarn = parsed.value.object.get("yarn").?.object;
    const cfg = parsed.value.object.get("config").?.object;

    const head_dim: u32 = @intCast(cfg.get("head_dim").?.integer);
    const partial: f32 = @floatCast(jsonF64(yarn.get("partial_rotary_factor").?));
    const base = jsonF64(yarn.get("rope_theta").?);
    const factor = jsonF64(yarn.get("factor").?);
    const beta_fast = jsonF64(yarn.get("beta_fast").?);
    const beta_slow = jsonF64(yarn.get("beta_slow").?);
    const orig_max: u32 = @intCast(yarn.get("original_max_position_embeddings").?.integer);

    const ref = yarn.get("freqs").?.array;
    const out = try testing.allocator.alloc(f64, ref.items.len);
    defer testing.allocator.free(out);
    computeYarnFreqs(out, head_dim, partial, base, factor, beta_fast, beta_slow, orig_max);
    for (ref.items, 0..) |item, i| {
        try testing.expectApproxEqRel(jsonF64(item), out[i], 1e-6);
    }
    std.debug.print("[laguna-yarn] {d} freqs match reference (max rel err < 1e-6)\n", .{ref.items.len});
}

fn jsonF64(v: std.json.Value) f64 {
    return switch (v) {
        .float => |f| f,
        .integer => |i| @floatFromInt(i),
        else => std.math.nan(f64),
    };
}

// ── Inkling (inkling_mm_model) forward helpers ──
// Reference: the checkpoint's bundled inkling_mlx/ package (Apache-2.0,
// parity-validated vs transformers PR #47347). Dtype discipline mirrors the
// reference EXACTLY: the residual stream runs in the checkpoint's dtype (bf16
// on the shipped builds — the dense mlp.global_scale tensors are STORED bf16,
// so no promotion), while the short convs, the router chain and the rel-bias
// build compute in f32 and the shared-expert sum is f32-then-cast.

const InklingSconvOut = struct { out: mlx.mlx_array, new_state: mlx.mlx_array };

/// Depthwise causal short-convolution with residual add, computed in fp32
/// (`InklingShortConvolution`). `prev_state` = the last kernel-1 f32 inputs
/// (null ⇒ zeros — sequence start). Returns the output in x's dtype and the
/// new f32 state; caller owns both.
fn inklingSconvCore(s: mlx.mlx_stream, x: mlx.mlx_array, w: mlx.mlx_array, prev_state: ?mlx.mlx_array) !InklingSconvOut {
    const in_dtype = mlx.mlx_array_dtype(x);
    const x_shape = mlx.getShape(x); // [B, S, C]
    const w_shape = mlx.getShape(w); // [C, K, 1]
    const kernel = w_shape[1];
    const channels = x_shape[2];

    var x32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(x32);
    try mlx.check(mlx.mlx_astype(&x32, x, .float32, s));
    var w32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(w32);
    try mlx.check(mlx.mlx_astype(&w32, w, .float32, s));

    var left = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(left);
    if (prev_state) |st| {
        try mlx.check(mlx.mlx_astype(&left, st, .float32, s));
    } else {
        const zshape = [_]c_int{ x_shape[0], kernel - 1, channels };
        try mlx.check(mlx.mlx_zeros(&left, &zshape, 3, .float32, s));
    }

    var conv_in = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(conv_in);
    {
        const arr = [_]mlx.mlx_array{ left, x32 };
        const vec = mlx.mlx_vector_array_new_data(&arr, 2);
        defer _ = mlx.mlx_vector_array_free(vec);
        try mlx.check(mlx.mlx_concatenate_axis(&conv_in, vec, 1, s));
    }

    // "valid" conv over [left, x] yields exactly S causal outputs.
    var conv_out = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(conv_out);
    try mlx.check(mlx.mlx_conv1d(&conv_out, conv_in, w32, 1, 0, 1, channels, s));

    var out32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(out32);
    try mlx.check(mlx.mlx_add(&out32, conv_out, x32, s));

    var new_state = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(new_state);
    {
        const start = [_]c_int{ 0, x_shape[1], 0 }; // last kernel-1 rows of [K-1+S]
        const stop = [_]c_int{ x_shape[0], x_shape[1] + kernel - 1, channels };
        const strides = [_]c_int{ 1, 1, 1 };
        try mlx.check(mlx.mlx_slice(&new_state, conv_in, &start, 3, &stop, 3, &strides, 3, s));
    }

    var out = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(out);
    try mlx.check(mlx.mlx_astype(&out, out32, in_dtype, s));
    return .{ .out = out, .new_state = new_state };
}

/// Hidden-state-conditioned relative position bias (`InklingRelativeLogits`):
/// rel_states [B, Lq, H, d_rel] × proj [d_rel, extent] → per-distance bias,
/// gathered per (q, kv) pair as bias[b,h,i,j] = profile[clip(qpos_i - kvpos_j)]
/// and zeroed outside 0 <= distance < extent. `kv_start` = the absolute
/// position of the view's first key (non-zero when a sliding-layer decode
/// reads the last-window KV view). Returns [B, H, Lq, kv_len] f32.
fn inklingRelBias(s: mlx.mlx_stream, rel_states: mlx.mlx_array, proj: mlx.mlx_array, q_start: i64, kv_len: c_int, kv_start: c_int) !mlx.mlx_array {
    const rs_shape = mlx.getShape(rel_states); // [B, Lq, H, d_rel]
    const batch = rs_shape[0];
    const lq = rs_shape[1];
    const heads = rs_shape[2];
    const extent = mlx.getShape(proj)[1];

    var rs32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(rs32);
    try mlx.check(mlx.mlx_astype(&rs32, rel_states, .float32, s));
    var proj32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(proj32);
    try mlx.check(mlx.mlx_astype(&proj32, proj, .float32, s));

    // [B, Lq, H, extent] → [B, H, Lq, extent]
    var rel_logits = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(rel_logits);
    try mlx.check(mlx.mlx_matmul(&rel_logits, rs32, proj32, s));
    var rel_t = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(rel_t);
    try mlx.check(mlx.mlx_transpose_axes(&rel_t, rel_logits, &[_]c_int{ 0, 2, 1, 3 }, 4, s));

    // distance[i, j] = (q_start + i) - j, [Lq, kv_len] int32
    var q_pos = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q_pos);
    try mlx.check(mlx.mlx_arange(&q_pos, @floatFromInt(q_start), @floatFromInt(q_start + lq), 1, .int32, s));
    var q_col = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q_col);
    try mlx.check(mlx.mlx_reshape(&q_col, q_pos, &[_]c_int{ lq, 1 }, 2, s));
    var kv_pos = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(kv_pos);
    try mlx.check(mlx.mlx_arange(&kv_pos, @floatFromInt(kv_start), @floatFromInt(kv_start + kv_len), 1, .int32, s));
    var distance = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(distance);
    try mlx.check(mlx.mlx_subtract(&distance, q_col, kv_pos, s));

    // gather = clip(distance, 0, extent-1), broadcast [B, H, Lq, kv_len]
    const zero_i = mlx.mlx_array_new_int(0);
    defer _ = mlx.mlx_array_free(zero_i);
    const max_i = mlx.mlx_array_new_int(extent - 1);
    defer _ = mlx.mlx_array_free(max_i);
    var lo = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(lo);
    try mlx.check(mlx.mlx_maximum(&lo, distance, zero_i, s));
    var gather = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gather);
    try mlx.check(mlx.mlx_minimum(&gather, lo, max_i, s));
    var gather4 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gather4);
    try mlx.check(mlx.mlx_reshape(&gather4, gather, &[_]c_int{ 1, 1, lq, kv_len }, 4, s));
    var gather_b = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gather_b);
    try mlx.check(mlx.mlx_broadcast_to(&gather_b, gather4, &[_]c_int{ batch, heads, lq, kv_len }, 4, s));

    var bias = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(bias);
    try mlx.check(mlx.mlx_take_along_axis(&bias, rel_t, gather_b, 3, s));

    // valid = 0 <= distance < extent (per the reference, additive-zero outside)
    var ge0 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(ge0);
    try mlx.check(mlx.mlx_greater_equal(&ge0, distance, zero_i, s));
    const ext_i = mlx.mlx_array_new_int(extent);
    defer _ = mlx.mlx_array_free(ext_i);
    var lt_ext = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(lt_ext);
    try mlx.check(mlx.mlx_less(&lt_ext, distance, ext_i, s));
    var valid = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(valid);
    try mlx.check(mlx.mlx_logical_and(&valid, ge0, lt_ext, s));
    var valid4 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(valid4);
    try mlx.check(mlx.mlx_reshape(&valid4, valid, &[_]c_int{ 1, 1, lq, kv_len }, 4, s));

    const zero_f = mlx.mlx_array_new_float(0.0);
    defer _ = mlx.mlx_array_free(zero_f);
    var out = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(out);
    try mlx.check(mlx.mlx_where(&out, valid4, bias, zero_f, s));
    return out;
}

/// Fold the causal (or sliding-window) constraint into the rel bias as ONE
/// additive mask: where allowed, the bias; elsewhere -1e30 (the reference's
/// NEG_INF — built with where, never indicator × -inf). Returns f32
/// [.., Lq, kv_len] broadcastable against the bias shape.
fn inklingCombineMask(s: mlx.mlx_stream, bias: mlx.mlx_array, q_start: c_int, kv_len: c_int, kv_start: c_int, window: ?c_int) !mlx.mlx_array {
    const b_shape = mlx.getShape(bias); // [B, H, Lq, kv_len]
    const lq = b_shape[2];
    var q_pos = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q_pos);
    try mlx.check(mlx.mlx_arange(&q_pos, @floatFromInt(q_start), @floatFromInt(q_start + lq), 1, .int32, s));
    var q_col = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q_col);
    try mlx.check(mlx.mlx_reshape(&q_col, q_pos, &[_]c_int{ lq, 1 }, 2, s));
    var kv_pos = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(kv_pos);
    try mlx.check(mlx.mlx_arange(&kv_pos, @floatFromInt(kv_start), @floatFromInt(kv_start + kv_len), 1, .int32, s));
    var distance = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(distance);
    try mlx.check(mlx.mlx_subtract(&distance, q_col, kv_pos, s));

    const zero_i = mlx.mlx_array_new_int(0);
    defer _ = mlx.mlx_array_free(zero_i);
    var allowed = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(allowed);
    try mlx.check(mlx.mlx_greater_equal(&allowed, distance, zero_i, s));
    if (window) |w| {
        const w_i = mlx.mlx_array_new_int(w);
        defer _ = mlx.mlx_array_free(w_i);
        var in_win = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(in_win);
        try mlx.check(mlx.mlx_less(&in_win, distance, w_i, s));
        var both = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_logical_and(&both, allowed, in_win, s));
        _ = mlx.mlx_array_free(allowed);
        allowed = both;
    }
    var allowed4 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(allowed4);
    try mlx.check(mlx.mlx_reshape(&allowed4, allowed, &[_]c_int{ 1, 1, lq, kv_len }, 4, s));

    const neg_inf = mlx.mlx_array_new_float(-1e30);
    defer _ = mlx.mlx_array_free(neg_inf);
    var out = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(out);
    try mlx.check(mlx.mlx_where(&out, allowed4, bias, neg_inf, s));
    return out;
}

/// Per-query log-scaling factor for global layers past the floor:
/// tau_i = 1 + alpha·ln(max((q_start + i + 1)/n_floor, 1)), f32 [1,1,Lq,1].
fn inklingLogScaleTau(s: mlx.mlx_stream, q_start: c_int, lq: c_int, n_floor: u32, alpha: f32) !mlx.mlx_array {
    var eff_n = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(eff_n);
    try mlx.check(mlx.mlx_arange(&eff_n, @floatFromInt(q_start + 1), @floatFromInt(q_start + lq + 1), 1, .float32, s));
    const floor_f = mlx.mlx_array_new_float(@floatFromInt(n_floor));
    defer _ = mlx.mlx_array_free(floor_f);
    var ratio = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(ratio);
    try mlx.check(mlx.mlx_divide(&ratio, eff_n, floor_f, s));
    const one_f = mlx.mlx_array_new_float(1.0);
    defer _ = mlx.mlx_array_free(one_f);
    var clamped = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(clamped);
    try mlx.check(mlx.mlx_maximum(&clamped, ratio, one_f, s));
    var logv = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(logv);
    try mlx.check(mlx.mlx_log(&logv, clamped, s));
    const alpha_f = mlx.mlx_array_new_float(alpha);
    defer _ = mlx.mlx_array_free(alpha_f);
    var scaled = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(scaled);
    try mlx.check(mlx.mlx_multiply(&scaled, logv, alpha_f, s));
    var tau_flat = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(tau_flat);
    try mlx.check(mlx.mlx_add(&tau_flat, scaled, one_f, s));
    var out = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(out);
    try mlx.check(mlx.mlx_reshape(&out, tau_flat, &[_]c_int{ 1, 1, lq, 1 }, 4, s));
    return out;
}

const InkgroupLimitedRouting = struct { topk_weights: mlx.mlx_array, topk_idx: mlx.mlx_array, shared_gammas: mlx.mlx_array };

/// The Inkling router chain (`InklingTopkRouter`), all in f32: sigmoid scores
/// + selection bias pick the top-k routed experts, then ONE softmax over the
/// logsigmoid of [selected routed logits, shared logits] produces the routed
/// weights AND the shared-expert gammas (the "sink"), scaled by
/// route_scale × global_scale. `logits` = x_f32 @ gate_weight.T [T, E+ns].
fn inklingRouterChain(s: mlx.mlx_stream, logits: mlx.mlx_array, bias: mlx.mlx_array, top_k: c_int, n_shared: c_int, route_scale: f32, global_scale: f32) !InkgroupLimitedRouting {
    const l_shape = mlx.getShape(logits); // [T, E+ns]
    const t_count = l_shape[0];
    const n_routed = l_shape[1] - n_shared;
    const strides2 = [_]c_int{ 1, 1 };

    var routed_logits = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(routed_logits);
    try mlx.check(mlx.mlx_slice(&routed_logits, logits, &[_]c_int{ 0, 0 }, 2, &[_]c_int{ t_count, n_routed }, 2, &strides2, 2, s));
    var shared_logits = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(shared_logits);
    try mlx.check(mlx.mlx_slice(&shared_logits, logits, &[_]c_int{ 0, n_routed }, 2, &[_]c_int{ t_count, l_shape[1] }, 2, &strides2, 2, s));

    // top-k on sigmoid(routed) + bias (selection only; weights use the logits)
    var scores = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(scores);
    try mlx.check(mlx.mlx_sigmoid(&scores, routed_logits, s));
    var choice = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(choice);
    try mlx.check(mlx.mlx_add(&choice, scores, bias, s));
    var neg_choice = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(neg_choice);
    try mlx.check(mlx.mlx_negative(&neg_choice, choice, s));
    var part = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(part);
    try mlx.check(mlx.mlx_argpartition_axis(&part, neg_choice, top_k - 1, -1, s));
    var topk_idx = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(topk_idx);
    {
        var sliced = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(sliced);
        try mlx.check(mlx.mlx_slice(&sliced, part, &[_]c_int{ 0, 0 }, 2, &[_]c_int{ t_count, top_k }, 2, &strides2, 2, s));
        try mlx.check(mlx.mlx_astype(&topk_idx, sliced, .uint32, s));
    }

    var gathered = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gathered);
    try mlx.check(mlx.mlx_take_along_axis(&gathered, routed_logits, topk_idx, 1, s));
    var topk_logits = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(topk_logits);
    {
        const arr = [_]mlx.mlx_array{ gathered, shared_logits };
        const vec = mlx.mlx_vector_array_new_data(&arr, 2);
        defer _ = mlx.mlx_vector_array_free(vec);
        try mlx.check(mlx.mlx_concatenate_axis(&topk_logits, vec, 1, s));
    }

    // logsigmoid(x) = -logaddexp(0, -x), then softmax over [K + ns]
    var neg_logits = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(neg_logits);
    try mlx.check(mlx.mlx_negative(&neg_logits, topk_logits, s));
    const zero_f = mlx.mlx_array_new_float(0.0);
    defer _ = mlx.mlx_array_free(zero_f);
    var lae = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(lae);
    try mlx.check(mlx.mlx_logaddexp(&lae, zero_f, neg_logits, s));
    var log_probs = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(log_probs);
    try mlx.check(mlx.mlx_negative(&log_probs, lae, s));
    var soft = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(soft);
    try mlx.check(mlx.mlx_softmax_axis(&soft, log_probs, -1, true, s));
    const scale_f = mlx.mlx_array_new_float(route_scale * global_scale);
    defer _ = mlx.mlx_array_free(scale_f);
    var weights = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(weights);
    try mlx.check(mlx.mlx_multiply(&weights, soft, scale_f, s));

    var topk_weights = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(topk_weights);
    try mlx.check(mlx.mlx_slice(&topk_weights, weights, &[_]c_int{ 0, 0 }, 2, &[_]c_int{ t_count, top_k }, 2, &strides2, 2, s));
    var shared_gammas = mlx.mlx_array_new();
    errdefer _ = mlx.mlx_array_free(shared_gammas);
    try mlx.check(mlx.mlx_slice(&shared_gammas, weights, &[_]c_int{ 0, top_k }, 2, &[_]c_int{ t_count, top_k + n_shared }, 2, &strides2, 2, s));

    return .{ .topk_weights = topk_weights, .topk_idx = topk_idx, .shared_gammas = shared_gammas };
}

fn jsonToMlxArray(allocator: std.mem.Allocator, v: std.json.Value) !mlx.mlx_array {
    var shape: [8]c_int = undefined;
    var ndim: usize = 0;
    var cur = v;
    while (cur == .array) {
        if (ndim >= 8) return error.TooManyDims;
        shape[ndim] = @intCast(cur.array.items.len);
        ndim += 1;
        if (cur.array.items.len == 0) break;
        cur = cur.array.items[0];
    }
    var total: usize = 1;
    for (shape[0..ndim]) |d| total *= @intCast(d);
    const data = try allocator.alloc(f32, total);
    defer allocator.free(data);
    var idx: usize = 0;
    const Fill = struct {
        fn fill(val: std.json.Value, out: []f32, i: *usize) void {
            switch (val) {
                .array => |a| for (a.items) |item| fill(item, out, i),
                else => {
                    out[i.*] = @floatCast(jsonF64(val));
                    i.* += 1;
                },
            }
        }
    };
    Fill.fill(v, data, &idx);
    return mlx.mlx_array_new_data(data.ptr, &shape, @intCast(ndim), .float32);
}

fn loadInklingFixtures(allocator: std.mem.Allocator) !?std.json.Parsed(std.json.Value) {
    const path_z = std.c.getenv("INKLING_FIXTURES") orelse return null;
    const path = std.mem.span(path_z);
    if (path.len == 0) return null;
    const io = std.Io.Threaded.global_single_threaded.io();
    const file = try std.Io.Dir.openFileAbsolute(io, path, .{});
    defer file.close(io);
    var read_buf: [4096]u8 = undefined;
    var reader_state = file.reader(io, &read_buf);
    const data = try reader_state.interface.allocRemaining(allocator, .limited(1 << 26));
    defer allocator.free(data);
    return try std.json.parseFromSlice(std.json.Value, allocator, data, .{});
}

/// Max |a-b| between two same-shaped float arrays, with a NaN guard (a NaN
/// candidate must FAIL, never score 0 — the parity-loop finiteness rule).
pub fn maxAbsDiffF32(a: mlx.mlx_array, b: mlx.mlx_array, s: mlx.mlx_stream) !f32 {
    // materializedOwnedCopy: a same-dtype astype is a NO-OP view and a slice's
    // raw data pointer walks the PARENT's physical layout — force a contiguous
    // owned buffer before touching bytes.
    var a_t = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(a_t);
    try mlx.check(mlx.mlx_astype(&a_t, a, .float32, s));
    const a32 = try materializedOwnedCopy(s, a_t);
    defer _ = mlx.mlx_array_free(a32);
    var b_t = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(b_t);
    try mlx.check(mlx.mlx_astype(&b_t, b, .float32, s));
    const b32 = try materializedOwnedCopy(s, b_t);
    defer _ = mlx.mlx_array_free(b32);
    try mlx.check(mlx.mlx_array_eval(a32));
    try mlx.check(mlx.mlx_array_eval(b32));
    const n = mlx.mlx_array_size(a32);
    if (n != mlx.mlx_array_size(b32)) return error.ShapeMismatch;
    const pa = mlx.mlx_array_data_float32(a32) orelse return error.NoData;
    const pb = mlx.mlx_array_data_float32(b32) orelse return error.NoData;
    var max_err: f32 = 0;
    for (0..n) |i| {
        const d = @abs(pa[i] - pb[i]);
        if (!std.math.isFinite(d)) return error.NonFiniteValue;
        if (d > max_err) max_err = d;
    }
    return max_err;
}

test "inkling sconv parity vs reference ShortConvolution (INKLING_FIXTURES)" {
    const allocator = testing.allocator;
    var parsed = (try loadInklingFixtures(allocator)) orelse return error.SkipZigTest;
    defer parsed.deinit();
    const sc = parsed.value.object.get("sconv").?.object;
    const s = mlx.gpuStream();

    const w = try jsonToMlxArray(allocator, sc.get("weight").?);
    defer _ = mlx.mlx_array_free(w);
    const x = try jsonToMlxArray(allocator, sc.get("x").?);
    defer _ = mlx.mlx_array_free(x);
    const y_ref = try jsonToMlxArray(allocator, sc.get("y_full").?);
    defer _ = mlx.mlx_array_free(y_ref);
    const state_ref = try jsonToMlxArray(allocator, sc.get("final_cache_state").?);
    defer _ = mlx.mlx_array_free(state_ref);

    // Full-sequence (no prior state).
    const full = try inklingSconvCore(s, x, w, null);
    defer _ = mlx.mlx_array_free(full.out);
    defer _ = mlx.mlx_array_free(full.new_state);
    try testing.expect(try maxAbsDiffF32(full.out, y_ref, s) < 1e-5);

    // Incremental: one position at a time through the carried state must
    // reproduce the full-sequence output AND the reference's final state.
    const x_shape = mlx.getShape(x);
    const seq: usize = @intCast(x_shape[1]);
    var state: ?mlx.mlx_array = null;
    defer if (state) |st| {
        _ = mlx.mlx_array_free(st);
    };
    var worst: f32 = 0;
    for (0..seq) |t| {
        var xt = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(xt);
        const start = [_]c_int{ 0, @intCast(t), 0 };
        const stop = [_]c_int{ x_shape[0], @intCast(t + 1), x_shape[2] };
        const strides = [_]c_int{ 1, 1, 1 };
        try mlx.check(mlx.mlx_slice(&xt, x, &start, 3, &stop, 3, &strides, 3, s));
        const step = try inklingSconvCore(s, xt, w, state);
        if (state) |st| _ = mlx.mlx_array_free(st);
        state = step.new_state;
        defer _ = mlx.mlx_array_free(step.out);
        var yt = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(yt);
        try mlx.check(mlx.mlx_slice(&yt, y_ref, &start, 3, &stop, 3, &strides, 3, s));
        const e = try maxAbsDiffF32(step.out, yt, s);
        if (e > worst) worst = e;
    }
    try testing.expect(worst < 1e-5);
    try testing.expect(try maxAbsDiffF32(state.?, state_ref, s) < 1e-5);
    std.debug.print("[inkling-sconv] full+incremental parity ok (worst step err {e:.3})\n", .{worst});
}

test "inkling relative-logits bias parity vs reference (INKLING_FIXTURES)" {
    const allocator = testing.allocator;
    var parsed = (try loadInklingFixtures(allocator)) orelse return error.SkipZigTest;
    defer parsed.deinit();
    const rb = parsed.value.object.get("rel_bias").?.object;
    const s = mlx.gpuStream();

    const proj = try jsonToMlxArray(allocator, rb.get("proj").?);
    defer _ = mlx.mlx_array_free(proj);

    // Prefill: Lq == Lkv, start 0.
    {
        const pf = rb.get("prefill").?.object;
        const rel_states = try jsonToMlxArray(allocator, pf.get("rel_states").?);
        defer _ = mlx.mlx_array_free(rel_states);
        const bias_ref = try jsonToMlxArray(allocator, pf.get("bias").?);
        defer _ = mlx.mlx_array_free(bias_ref);
        const shape = mlx.getShape(rel_states);
        const bias = try inklingRelBias(s, rel_states, proj, 0, shape[1], 0);
        defer _ = mlx.mlx_array_free(bias);
        try testing.expect(try maxAbsDiffF32(bias, bias_ref, s) < 1e-5);
    }
    // Decode: Lq = 1 at a position past the extent (zero-beyond-extent region).
    {
        const dc = rb.get("decode").?.object;
        const rel_states = try jsonToMlxArray(allocator, dc.get("rel_states").?);
        defer _ = mlx.mlx_array_free(rel_states);
        const bias_ref = try jsonToMlxArray(allocator, dc.get("bias").?);
        defer _ = mlx.mlx_array_free(bias_ref);
        const kv_len: c_int = @intCast(dc.get("kv_len").?.integer);
        const q_pos: i64 = dc.get("q_pos").?.integer;
        const bias = try inklingRelBias(s, rel_states, proj, q_pos, kv_len, 0);
        defer _ = mlx.mlx_array_free(bias);
        try testing.expect(try maxAbsDiffF32(bias, bias_ref, s) < 1e-5);
    }
    std.debug.print("[inkling-relbias] prefill+decode parity ok\n", .{});
}

test "inkling router chain parity vs reference (INKLING_FIXTURES)" {
    const allocator = testing.allocator;
    var parsed = (try loadInklingFixtures(allocator)) orelse return error.SkipZigTest;
    defer parsed.deinit();
    const rt = parsed.value.object.get("router").?.object;
    const cfgj = parsed.value.object.get("config").?.object;
    const s = mlx.gpuStream();

    const w = try jsonToMlxArray(allocator, rt.get("weight").?); // [E+ns, H]
    defer _ = mlx.mlx_array_free(w);
    const bias = try jsonToMlxArray(allocator, rt.get("bias").?); // [E]
    defer _ = mlx.mlx_array_free(bias);
    const x = try jsonToMlxArray(allocator, rt.get("x").?); // [1, T, H]
    defer _ = mlx.mlx_array_free(x);
    const tw_ref = try jsonToMlxArray(allocator, rt.get("topk_weights").?);
    defer _ = mlx.mlx_array_free(tw_ref);
    const sg_ref = try jsonToMlxArray(allocator, rt.get("shared_gammas").?);
    defer _ = mlx.mlx_array_free(sg_ref);

    const top_k: c_int = @intCast(cfgj.get("num_experts_per_tok").?.integer);
    const n_shared: c_int = @intCast(cfgj.get("n_shared_experts").?.integer);
    const route_scale: f32 = @floatCast(jsonF64(cfgj.get("route_scale").?));
    const global_scale: f32 = @floatCast(jsonF64(rt.get("global_scale").?));

    // logits = flatten(x) @ w.T in f32 (the caller's job in the forward).
    const x_shape = mlx.getShape(x);
    var xf = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(xf);
    const flat_shape = [_]c_int{ x_shape[0] * x_shape[1], x_shape[2] };
    try mlx.check(mlx.mlx_reshape(&xf, x, &flat_shape, 2, s));
    var wt = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(wt);
    try mlx.check(mlx.mlx_transpose_axes(&wt, w, &[_]c_int{ 1, 0 }, 2, s));
    var logits = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(logits);
    try mlx.check(mlx.mlx_matmul(&logits, xf, wt, s));

    const r = try inklingRouterChain(s, logits, bias, top_k, n_shared, route_scale, global_scale);
    defer _ = mlx.mlx_array_free(r.topk_weights);
    defer _ = mlx.mlx_array_free(r.topk_idx);
    defer _ = mlx.mlx_array_free(r.shared_gammas);

    // Indices: order within the top-k is irrelevant downstream, but the
    // reference dumps argpartition order — compare as SETS per token, and
    // weights via a value-sorted comparison per token.
    const ti_ref = rt.get("topk_idx").?.array;
    const idx_c = try materializedOwnedCopy(s, r.topk_idx);
    defer _ = mlx.mlx_array_free(idx_c);
    try mlx.check(mlx.mlx_array_eval(idx_c));
    const ip = mlx.mlx_array_data_uint32(idx_c) orelse return error.NoData;
    const T: usize = @intCast(flat_shape[0]);
    const K: usize = @intCast(top_k);
    for (0..T) |t| {
        const row_ref = ti_ref.items[t].array;
        for (0..K) |k| {
            const want: u32 = @intCast(row_ref.items[k].integer);
            var found = false;
            for (0..K) |k2| {
                if (ip[t * K + k2] == want) found = true;
            }
            try testing.expect(found);
        }
    }
    // Weights: match by expert id (reference order vs ours may differ).
    const tw_c = try materializedOwnedCopy(s, r.topk_weights);
    defer _ = mlx.mlx_array_free(tw_c);
    try mlx.check(mlx.mlx_array_eval(tw_c));
    const wp = mlx.mlx_array_data_float32(tw_c) orelse return error.NoData;
    try mlx.check(mlx.mlx_array_eval(tw_ref));
    const wr = mlx.mlx_array_data_float32(tw_ref) orelse return error.NoData;
    for (0..T) |t| {
        const row_ref = ti_ref.items[t].array;
        for (0..K) |k| {
            const expert: u32 = @intCast(row_ref.items[k].integer);
            var ours: f32 = std.math.nan(f32);
            for (0..K) |k2| {
                if (ip[t * K + k2] == expert) ours = wp[t * K + k2];
            }
            try testing.expect(std.math.isFinite(ours));
            try testing.expect(@abs(ours - wr[t * K + k]) < 1e-4);
        }
    }
    try testing.expect(try maxAbsDiffF32(r.shared_gammas, sg_ref, s) < 1e-4);
    std.debug.print("[inkling-router] top-k select + sink weights parity ok\n", .{});
}

test "gdnGateChain matches g = exp(-exp(A_log) * softplus(a + dt_bias))" {
    const s = mlx.gpuStream();

    // Hv = 2 heads, B=1, S=1. Hand-computable fixtures:
    //   head 0: A_log=0, a=0, dt_bias=0 → g = exp(-1 * softplus(0)) = exp(-ln2) = 0.5
    //   head 1: A_log=ln2, a=0, dt_bias=0 → g = exp(-2 * ln2) = 0.25
    const a_log_data = [_]f32{ 0.0, @log(2.0) };
    const hv_shape = [_]c_int{2};
    const A_log = mlx.mlx_array_new_data(&a_log_data, &hv_shape, 1, .float32);
    defer _ = mlx.mlx_array_free(A_log);

    const a_data = [_]f32{ 0.0, 0.0 };
    const a_shape = [_]c_int{ 1, 1, 2 };
    const a = mlx.mlx_array_new_data(&a_data, &a_shape, 3, .float32);
    defer _ = mlx.mlx_array_free(a);

    const dt_data = [_]f32{ 0.0, 0.0 };
    const dt_bias = mlx.mlx_array_new_data(&dt_data, &hv_shape, 1, .float32);
    defer _ = mlx.mlx_array_free(dt_bias);

    const g = try gdnGateChain(A_log, a, dt_bias, s);
    defer _ = mlx.mlx_array_free(g);

    var g_f32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(g_f32);
    try mlx.check(mlx.mlx_astype(&g_f32, g, .float32, s));
    try mlx.check(mlx.mlx_array_eval(g_f32));

    const gd = mlx.mlx_array_data_float32(g_f32) orelse return error.InvalidDtype;
    // bf16 round-trip tolerance
    const tol: f32 = 5e-3;
    try testing.expect(@abs(gd[0] - 0.5) < tol);
    try testing.expect(@abs(gd[1] - 0.25) < tol);
}

// Helper for the GDN seq-kernel parity test below: run the recurrence via the
// requested kernel variant and return the FINAL state [B,Hv,Dv,Dk] as f32.
fn gdnTestRun(comptime seq: bool, comptime vec: bool, q: mlx.mlx_array, k: mlx.mlx_array, v: mlx.mlx_array, g: mlx.mlx_array, beta: mlx.mlx_array, state_in: mlx.mlx_array, B: c_int, T: c_int, Hk: c_int, Hv: c_int, Dk: c_int, Dv: c_int, s: mlx.mlx_stream) !mlx.mlx_array {
    const T_scalar = mlx.mlx_array_new_int(T);
    defer _ = mlx.mlx_array_free(T_scalar);
    const y_shape = [_]c_int{ B, T, Hv, Dv };
    const config = mlx.mlx_fast_metal_kernel_config_new();
    defer _ = mlx.mlx_fast_metal_kernel_config_free(config);
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_output_arg(config, &y_shape, 4, .bfloat16));
    if (seq) {
        const ss_shape = [_]c_int{ T, B, Hv, Dv, Dk };
        try mlx.check(mlx.mlx_fast_metal_kernel_config_add_output_arg(config, &ss_shape, 5, .bfloat16));
        // Final state is its own output (written from registers); the seq
        // buffer's last row is deliberately UNWRITTEN (capture-tail trim).
        const so_shape = [_]c_int{ B, Hv, Dv, Dk };
        try mlx.check(mlx.mlx_fast_metal_kernel_config_add_output_arg(config, &so_shape, 4, .bfloat16));
    } else {
        const so_shape = [_]c_int{ B, Hv, Dv, Dk };
        try mlx.check(mlx.mlx_fast_metal_kernel_config_add_output_arg(config, &so_shape, 4, .bfloat16));
    }
    try mlx.check(mlx.mlx_fast_metal_kernel_config_set_grid(config, 32, Dv, B * Hv));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_set_thread_group(config, 32, 4, 1));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_dtype(config, "InT", .bfloat16));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_dtype(config, "StT", .bfloat16));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_dtype(config, "OutT", .bfloat16));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Dk", Dk));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Dv", Dv));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Hk", Hk));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Hv", Hv));

    var outputs_vec = mlx.mlx_vector_array_new();
    defer _ = mlx.mlx_vector_array_free(outputs_vec);
    if (seq) {
        const seq_stride = mlx.mlx_array_new_int(B * Hv * Dv * Dk);
        defer _ = mlx.mlx_array_free(seq_stride);
        const inputs_arr = [_]mlx.mlx_array{ q, k, v, g, beta, state_in, T_scalar, seq_stride };
        const inputs_vec = mlx.mlx_vector_array_new_data(&inputs_arr, inputs_arr.len);
        defer _ = mlx.mlx_vector_array_free(inputs_vec);
        const kern = try getGdnKernelSeq(vec);
        try mlx.check(mlx.mlx_fast_metal_kernel_apply(&outputs_vec, kern, inputs_vec, config, s));
        // Final state comes from the dedicated state_out output — after the
        // capture-tail trim, state_seq[T-1] is never written.
        var out = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_vector_array_get(&out, outputs_vec, 2));
        return out;
    } else {
        const inputs_arr = [_]mlx.mlx_array{ q, k, v, g, beta, state_in, T_scalar };
        const inputs_vec = mlx.mlx_vector_array_new_data(&inputs_arr, inputs_arr.len);
        defer _ = mlx.mlx_vector_array_free(inputs_vec);
        const kern = try getGdnKernel(vec);
        try mlx.check(mlx.mlx_fast_metal_kernel_apply(&outputs_vec, kern, inputs_vec, config, s));
        var out = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_vector_array_get(&out, outputs_vec, 1));
        return out;
    }
}

test "GDN seq-kernel final state matches single-state kernel (PLD capture parity)" {
    const s = mlx.gpuStream();
    const B: c_int = 1;
    const T: c_int = 4;
    const Hk: c_int = 1;
    const Hv: c_int = 2;
    const Dk: c_int = 128; // n_per_t = Dk/32 = 4 (matches real GatedDeltaNet head dim)
    const Dv: c_int = 4;

    // Deterministic pseudo-random inputs in [-0.5, 0.5].
    var prng = std.Random.DefaultPrng.init(0xC0FFEE);
    const rnd = prng.random();
    const qn: usize = @intCast(B * T * Hk * Dk);
    const vn: usize = @intCast(B * T * Hv * Dv);
    const gn: usize = @intCast(B * T * Hv);
    const sn: usize = @intCast(B * Hv * Dv * Dk);
    const qd = try testing.allocator.alloc(f32, qn);
    defer testing.allocator.free(qd);
    const kd = try testing.allocator.alloc(f32, qn);
    defer testing.allocator.free(kd);
    const vd = try testing.allocator.alloc(f32, vn);
    defer testing.allocator.free(vd);
    const gd = try testing.allocator.alloc(f32, gn);
    defer testing.allocator.free(gd);
    const bd = try testing.allocator.alloc(f32, gn);
    defer testing.allocator.free(bd);
    const sd = try testing.allocator.alloc(f32, sn);
    defer testing.allocator.free(sd);
    for (qd) |*x| x.* = rnd.float(f32) - 0.5;
    for (kd) |*x| x.* = rnd.float(f32) - 0.5;
    for (vd) |*x| x.* = rnd.float(f32) - 0.5;
    for (gd) |*x| x.* = 0.5 + 0.4 * rnd.float(f32); // decay in (0.5,0.9)
    for (bd) |*x| x.* = rnd.float(f32);
    for (sd) |*x| x.* = rnd.float(f32) - 0.5;

    const qsh = [_]c_int{ B, T, Hk, Dk };
    const vsh = [_]c_int{ B, T, Hv, Dv };
    const gsh = [_]c_int{ B, T, Hv };
    const ssh = [_]c_int{ B, Hv, Dv, Dk };
    const q32 = mlx.mlx_array_new_data(qd.ptr, &qsh, 4, .float32);
    defer _ = mlx.mlx_array_free(q32);
    const k32 = mlx.mlx_array_new_data(kd.ptr, &qsh, 4, .float32);
    defer _ = mlx.mlx_array_free(k32);
    const v32 = mlx.mlx_array_new_data(vd.ptr, &vsh, 4, .float32);
    defer _ = mlx.mlx_array_free(v32);
    const g32 = mlx.mlx_array_new_data(gd.ptr, &gsh, 3, .float32);
    defer _ = mlx.mlx_array_free(g32);
    const b32 = mlx.mlx_array_new_data(bd.ptr, &gsh, 3, .float32);
    defer _ = mlx.mlx_array_free(b32);
    const st32 = mlx.mlx_array_new_data(sd.ptr, &ssh, 4, .float32);
    defer _ = mlx.mlx_array_free(st32);

    // Cast inputs to bf16 (kernel expects InT/StT = bf16).
    var q = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q);
    var kk = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(kk);
    var v = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(v);
    var g = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(g);
    var beta = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(beta);
    var st = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(st);
    try mlx.check(mlx.mlx_astype(&q, q32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&kk, k32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&v, v32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&g, g32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&beta, b32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&st, st32, .bfloat16, s));

    const state_a = try gdnTestRun(false, false, q, kk, v, g, beta, st, B, T, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(state_a);
    const state_b = try gdnTestRun(true, false, q, kk, v, g, beta, st, B, T, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(state_b);

    var a32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(a32);
    var bb32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(bb32);
    try mlx.check(mlx.mlx_astype(&a32, state_a, .float32, s));
    try mlx.check(mlx.mlx_astype(&bb32, state_b, .float32, s));
    try mlx.check(mlx.mlx_array_eval(a32));
    try mlx.check(mlx.mlx_array_eval(bb32));
    const ad = mlx.mlx_array_data_float32(a32) orelse return error.InvalidDtype;
    const bd2 = mlx.mlx_array_data_float32(bb32) orelse return error.InvalidDtype;
    var max_diff: f32 = 0;
    for (0..sn) |i| max_diff = @max(max_diff, @abs(ad[i] - bd2[i]));
    // Both write the same bf16-cast state — expect exact (allow tiny slack).
    try testing.expect(max_diff < 1e-3);

    // Intermediate-position parity: the state captured at position `accepted`
    // of a length-T seq run must equal a fresh normal-kernel run over just the
    // first (accepted+1) tokens — this is exactly what partial-accept rollback
    // relies on. Check accepted = 1 (run length 2).
    const acc_run: c_int = 2; // accepted+1 = 2 tokens
    const q2_sh = [_]c_int{ B, acc_run, Hk, Dk };
    const v2_sh = [_]c_int{ B, acc_run, Hv, Dv };
    const g2_sh = [_]c_int{ B, acc_run, Hv };
    const z3 = [_]c_int{ 1, 1, 1, 1 };
    var q2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q2);
    var k2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(k2);
    var v2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(v2);
    var g2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(g2);
    var b2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(b2);
    try mlx.check(mlx.mlx_slice(&q2, q, &[_]c_int{ 0, 0, 0, 0 }, 4, &q2_sh, 4, &z3, 4, s));
    try mlx.check(mlx.mlx_slice(&k2, kk, &[_]c_int{ 0, 0, 0, 0 }, 4, &q2_sh, 4, &z3, 4, s));
    try mlx.check(mlx.mlx_slice(&v2, v, &[_]c_int{ 0, 0, 0, 0 }, 4, &v2_sh, 4, &z3, 4, s));
    try mlx.check(mlx.mlx_slice(&g2, g, &[_]c_int{ 0, 0, 0 }, 3, &g2_sh, 3, &[_]c_int{ 1, 1, 1 }, 3, s));
    try mlx.check(mlx.mlx_slice(&b2, beta, &[_]c_int{ 0, 0, 0 }, 3, &g2_sh, 3, &[_]c_int{ 1, 1, 1 }, 3, s));

    const ref2 = try gdnTestRun(false, false, q2, k2, v2, g2, b2, st, B, acc_run, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(ref2);

    // Pull position 1 out of the length-T seq run.
    const state_seq_full = try gdnTestRunSeqAt(q, kk, v, g, beta, st, B, T, Hk, Hv, Dk, Dv, 1, s);
    defer _ = mlx.mlx_array_free(state_seq_full);

    var r32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(r32);
    var p32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(p32);
    try mlx.check(mlx.mlx_astype(&r32, ref2, .float32, s));
    try mlx.check(mlx.mlx_astype(&p32, state_seq_full, .float32, s));
    try mlx.check(mlx.mlx_array_eval(r32));
    try mlx.check(mlx.mlx_array_eval(p32));
    const rd = mlx.mlx_array_data_float32(r32) orelse return error.InvalidDtype;
    const pd = mlx.mlx_array_data_float32(p32) orelse return error.InvalidDtype;
    var mid_diff: f32 = 0;
    for (0..sn) |i| mid_diff = @max(mid_diff, @abs(rd[i] - pd[i]));
    try testing.expect(mid_diff < 1e-3);
}

test "joinableCols: a KDA q/k/v trio joins only when all three are quantized alike" {
    const t = std.testing;
    // Uniform 4-bit: all three pack to the same width.
    try t.expect(joinableCols(&[_]c_int{ 192, 192, 192 }));
    // Dense bf16: the trailing dim is the input width, still uniform.
    try t.expect(joinableCols(&[_]c_int{ 1536, 1536, 1536 }));
    // Bias-less quant: no scales at all, all zeros — uniform.
    try t.expect(joinableCols(&[_]c_int{ 0, 0, 0 }));
    // q at 8-bit beside k/v at 4-bit: mlx's concatenate rejects this at a
    // level we cannot catch, so the loader has to see it first.
    try t.expect(!joinableCols(&[_]c_int{ 384, 192, 192 }));
    try t.expect(!joinableCols(&[_]c_int{ 192, 192, 96 }));
    try t.expect(!joinableCols(&[_]c_int{}));
}

test "GDN vectorized-gate kernel: a per-channel gate that is UNIFORM per head equals the scalar kernel" {
    // KDA gates each state element by its own key channel. The invariant that
    // pins the indexing: broadcast a per-head decay across that head's Dk
    // channels and the `_vec` kernel must reproduce the scalar kernel BIT FOR
    // BIT — same recurrence, same reduction order, only the gate fetch differs.
    // A wrong stride/base in the `_vec` arm (reading head 0's channel for every
    // head, or walking Hv instead of Hv*Dk per step) survives every "output is
    // finite and roughly decays" check but fails this one.
    const s = mlx.gpuStream();
    const B: c_int = 1;
    const T: c_int = 5;
    const Hk: c_int = 2;
    const Hv: c_int = 2;
    const Dk: c_int = 128;
    const Dv: c_int = 128;

    var prng = std.Random.DefaultPrng.init(0x11CE);
    const rnd = prng.random();
    const qn: usize = @intCast(B * T * Hk * Dk);
    const vn: usize = @intCast(B * T * Hv * Dv);
    const gn: usize = @intCast(B * T * Hv);
    const gvn: usize = @intCast(B * T * Hv * Dk);
    const sn: usize = @intCast(B * Hv * Dv * Dk);
    const qd = try testing.allocator.alloc(f32, qn);
    defer testing.allocator.free(qd);
    const kd = try testing.allocator.alloc(f32, qn);
    defer testing.allocator.free(kd);
    const vd = try testing.allocator.alloc(f32, vn);
    defer testing.allocator.free(vd);
    const gd = try testing.allocator.alloc(f32, gn);
    defer testing.allocator.free(gd);
    const gvd = try testing.allocator.alloc(f32, gvn);
    defer testing.allocator.free(gvd);
    const bd = try testing.allocator.alloc(f32, gn);
    defer testing.allocator.free(bd);
    const sd = try testing.allocator.alloc(f32, sn);
    defer testing.allocator.free(sd);
    for (qd) |*x| x.* = rnd.float(f32) - 0.5;
    for (kd) |*x| x.* = rnd.float(f32) - 0.5;
    for (vd) |*x| x.* = rnd.float(f32) - 0.5;
    for (gd) |*x| x.* = 0.5 + 0.4 * rnd.float(f32);
    for (bd) |*x| x.* = rnd.float(f32);
    for (sd) |*x| x.* = rnd.float(f32) - 0.5;
    // Broadcast each (token, head) decay across that head's Dk channels.
    for (0..gn) |i| {
        for (0..@as(usize, @intCast(Dk))) |c| gvd[i * @as(usize, @intCast(Dk)) + c] = gd[i];
    }

    const qsh = [_]c_int{ B, T, Hk, Dk };
    const vsh = [_]c_int{ B, T, Hv, Dv };
    const gsh = [_]c_int{ B, T, Hv };
    const gvsh = [_]c_int{ B, T, Hv, Dk };
    const ssh = [_]c_int{ B, Hv, Dv, Dk };
    const raw = [_]mlx.mlx_array{
        mlx.mlx_array_new_data(qd.ptr, &qsh, 4, .float32),
        mlx.mlx_array_new_data(kd.ptr, &qsh, 4, .float32),
        mlx.mlx_array_new_data(vd.ptr, &vsh, 4, .float32),
        mlx.mlx_array_new_data(gd.ptr, &gsh, 3, .float32),
        mlx.mlx_array_new_data(gvd.ptr, &gvsh, 4, .float32),
        mlx.mlx_array_new_data(bd.ptr, &gsh, 3, .float32),
        mlx.mlx_array_new_data(sd.ptr, &ssh, 4, .float32),
    };
    defer for (raw) |r| {
        _ = mlx.mlx_array_free(r);
    };
    var bf: [raw.len]mlx.mlx_array = undefined;
    for (raw, 0..) |r, i| {
        bf[i] = mlx.mlx_array_new();
        try mlx.check(mlx.mlx_astype(&bf[i], r, .bfloat16, s));
    }
    defer for (bf) |a| {
        _ = mlx.mlx_array_free(a);
    };
    const q = bf[0];
    const kk = bf[1];
    const v = bf[2];
    const g_head = bf[3];
    const g_chan = bf[4];
    const beta = bf[5];
    const st = bf[6];

    const state_scalar = try gdnTestRun(false, false, q, kk, v, g_head, beta, st, B, T, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(state_scalar);
    const state_vec = try gdnTestRun(false, true, q, kk, v, g_chan, beta, st, B, T, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(state_vec);

    var a32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(a32);
    var b32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(b32);
    try mlx.check(mlx.mlx_astype(&a32, state_scalar, .float32, s));
    try mlx.check(mlx.mlx_astype(&b32, state_vec, .float32, s));
    try mlx.check(mlx.mlx_array_eval(a32));
    try mlx.check(mlx.mlx_array_eval(b32));
    const ad = mlx.mlx_array_data_float32(a32) orelse return error.InvalidDtype;
    const bd2 = mlx.mlx_array_data_float32(b32) orelse return error.InvalidDtype;
    var max_diff: f32 = 0;
    var any_nonzero = false;
    for (0..sn) |i| {
        max_diff = @max(max_diff, @abs(ad[i] - bd2[i]));
        if (@abs(ad[i]) > 1e-3) any_nonzero = true;
    }
    // Guard the guard: an all-zero state would pass any diff check.
    try testing.expect(any_nonzero);
    try testing.expectEqual(@as(f32, 0), max_diff);

    // And the seq-capture variant of the same kernel agrees with its own
    // scalar twin, so spec rollback stays correct on a vector-gated arch.
    const seq_scalar = try gdnTestRun(true, false, q, kk, v, g_head, beta, st, B, T, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(seq_scalar);
    const seq_vec = try gdnTestRun(true, true, q, kk, v, g_chan, beta, st, B, T, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(seq_vec);
    var c32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(c32);
    var d32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(d32);
    try mlx.check(mlx.mlx_astype(&c32, seq_scalar, .float32, s));
    try mlx.check(mlx.mlx_astype(&d32, seq_vec, .float32, s));
    try mlx.check(mlx.mlx_array_eval(c32));
    try mlx.check(mlx.mlx_array_eval(d32));
    const cd = mlx.mlx_array_data_float32(c32) orelse return error.InvalidDtype;
    const dd = mlx.mlx_array_data_float32(d32) orelse return error.InvalidDtype;
    var seq_diff: f32 = 0;
    for (0..sn) |i| seq_diff = @max(seq_diff, @abs(cd[i] - dd[i]));
    try testing.expectEqual(@as(f32, 0), seq_diff);
}

test "kdaGateChain is the bounded-sigmoid gate, not a clamped softplus" {
    // g = exp(bound * sigmoid(exp(A_log) * (a + dt_bias))). Two properties
    // that a "clamp the softplus form at bound" misreading would break:
    //   1. the decay is bounded BELOW by exp(bound) but never reaches it;
    //   2. it is MONOTONICALLY DECREASING in `a` (large positive a ⇒ maximum
    //      forgetting), where the softplus form's magnitude is unbounded.
    const s = mlx.gpuStream();
    const bound: f32 = -5.0;
    const a_vals = [_]f32{ -8.0, 0.0, 4.0 };
    const shape = [_]c_int{3};
    const a_arr = mlx.mlx_array_new_data(&a_vals, &shape, 1, .float32);
    defer _ = mlx.mlx_array_free(a_arr);
    const zeros = [_]f32{ 0.0, 0.0, 0.0 };
    const dt = mlx.mlx_array_new_data(&zeros, &shape, 1, .float32);
    defer _ = mlx.mlx_array_free(dt);
    const a_log_vals = [_]f32{ 0.0, 0.0, 0.0 }; // exp(A_log) = 1
    const a_log = mlx.mlx_array_new_data(&a_log_vals, &shape, 1, .float32);
    defer _ = mlx.mlx_array_free(a_log);

    const g = try kdaGateChain(a_log, a_arr, dt, bound, s);
    defer _ = mlx.mlx_array_free(g);
    var g32 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(g32);
    try mlx.check(mlx.mlx_astype(&g32, g, .float32, s));
    try mlx.check(mlx.mlx_array_eval(g32));
    const gd = mlx.mlx_array_data_float32(g32) orelse return error.InvalidDtype;

    const floor = @exp(bound); // ~0.0067
    for (0..3) |i| {
        try testing.expect(gd[i] > floor);
        // The open upper bound closes in bf16: a very negative `a` gives a
        // decay of 0.9983, whose nearest bf16 IS 1.0 (spacing 2^-8 near one).
        // "No forgetting" is the correct limit, so assert the closed bound.
        try testing.expect(gd[i] <= 1.0);
    }
    try testing.expect(gd[0] > gd[1]);
    try testing.expect(gd[1] > gd[2]);
    // a = 0 ⇒ sigmoid = 0.5 ⇒ g = exp(bound/2). bf16 round-trip tolerance.
    try testing.expect(@abs(gd[1] - @exp(bound / 2.0)) < 5e-3);
}

// Like gdnTestRun(seq=true) but returns the state at an arbitrary position `pos`
// (not just the last) — mirrors what `ssmRollbackFromCapture` slices out.
fn gdnTestRunSeqAt(q: mlx.mlx_array, k: mlx.mlx_array, v: mlx.mlx_array, g: mlx.mlx_array, beta: mlx.mlx_array, state_in: mlx.mlx_array, B: c_int, T: c_int, Hk: c_int, Hv: c_int, Dk: c_int, Dv: c_int, pos: c_int, s: mlx.mlx_stream) !mlx.mlx_array {
    const T_scalar = mlx.mlx_array_new_int(T);
    defer _ = mlx.mlx_array_free(T_scalar);
    const y_shape = [_]c_int{ B, T, Hv, Dv };
    const config = mlx.mlx_fast_metal_kernel_config_new();
    defer _ = mlx.mlx_fast_metal_kernel_config_free(config);
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_output_arg(config, &y_shape, 4, .bfloat16));
    const ss_shape = [_]c_int{ T, B, Hv, Dv, Dk };
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_output_arg(config, &ss_shape, 5, .bfloat16));
    const so_shape = [_]c_int{ B, Hv, Dv, Dk };
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_output_arg(config, &so_shape, 4, .bfloat16));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_set_grid(config, 32, Dv, B * Hv));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_set_thread_group(config, 32, 4, 1));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_dtype(config, "InT", .bfloat16));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_dtype(config, "StT", .bfloat16));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_dtype(config, "OutT", .bfloat16));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Dk", Dk));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Dv", Dv));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Hk", Hk));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Hv", Hv));
    const seq_stride = mlx.mlx_array_new_int(B * Hv * Dv * Dk);
    defer _ = mlx.mlx_array_free(seq_stride);
    const inputs_arr = [_]mlx.mlx_array{ q, k, v, g, beta, state_in, T_scalar, seq_stride };
    const inputs_vec = mlx.mlx_vector_array_new_data(&inputs_arr, inputs_arr.len);
    defer _ = mlx.mlx_vector_array_free(inputs_vec);
    const kern = try getGdnKernelSeq(false);
    var outputs_vec = mlx.mlx_vector_array_new();
    defer _ = mlx.mlx_vector_array_free(outputs_vec);
    try mlx.check(mlx.mlx_fast_metal_kernel_apply(&outputs_vec, kern, inputs_vec, config, s));
    var ss = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(ss);
    try mlx.check(mlx.mlx_vector_array_get(&ss, outputs_vec, 1));
    const start = [_]c_int{ pos, 0, 0, 0, 0 };
    const stop = [_]c_int{ pos + 1, B, Hv, Dv, Dk };
    const strides = [_]c_int{ 1, 1, 1, 1, 1 };
    var sliced = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(sliced);
    try mlx.check(mlx.mlx_slice(&sliced, ss, &start, 5, &stop, 5, &strides, 5, s));
    const fshape = [_]c_int{ B, Hv, Dv, Dk };
    var out = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_reshape(&out, sliced, &fshape, 4, s));
    return out;
}

// ── GDN blocked-seq kernel test harness ──

/// Truncate an f32 to a bf16-representable value (top 16 bits). Test inputs
/// pass through this so the f64 host reference and the bf16 kernels consume
/// IDENTICAL values — the only error left is kernel accumulation/rounding.
fn bf16Trunc(x: f32) f32 {
    const bits: u32 = @bitCast(x);
    return @bitCast(bits & 0xFFFF_0000);
}

const GdnHostRef = struct { y: []f32, state: []f32 };

/// f64 host ground truth of the exact GDN recurrence (the stock kernel's
/// math, per house rule: GPU parity is judged vs fp32+ ground truth, never
/// kernel-vs-kernel bf16 agreement).
fn gdnHostRef(
    al: std.mem.Allocator,
    qd: []const f32,
    kd: []const f32,
    vd: []const f32,
    gd: []const f32,
    bd: []const f32,
    sd: []const f32,
    B: usize,
    T: usize,
    Hk: usize,
    Hv: usize,
    Dk: usize,
    Dv: usize,
) !GdnHostRef {
    const y = try al.alloc(f32, B * T * Hv * Dv);
    errdefer al.free(y);
    const st_out = try al.alloc(f32, B * Hv * Dv * Dk);
    errdefer al.free(st_out);
    const S = try al.alloc(f64, Dv * Dk);
    defer al.free(S);
    const group = Hv / Hk;
    for (0..B) |b| {
        for (0..Hv) |hv| {
            const hk = hv / group;
            for (0..Dv) |dvi| {
                for (0..Dk) |dki| S[dvi * Dk + dki] = sd[((b * Hv + hv) * Dv + dvi) * Dk + dki];
            }
            for (0..T) |t| {
                const gt: f64 = gd[(b * T + t) * Hv + hv];
                const bt: f64 = bd[(b * T + t) * Hv + hv];
                const kbase = ((b * T + t) * Hk + hk) * Dk;
                for (S) |*x| x.* *= gt;
                for (0..Dv) |dvi| {
                    var kv: f64 = 0;
                    for (0..Dk) |dki| kv += S[dvi * Dk + dki] * @as(f64, kd[kbase + dki]);
                    const delta = (@as(f64, vd[((b * T + t) * Hv + hv) * Dv + dvi]) - kv) * bt;
                    var out: f64 = 0;
                    for (0..Dk) |dki| {
                        S[dvi * Dk + dki] += @as(f64, kd[kbase + dki]) * delta;
                        out += S[dvi * Dk + dki] * @as(f64, qd[kbase + dki]);
                    }
                    y[((b * T + t) * Hv + hv) * Dv + dvi] = @floatCast(out);
                }
            }
            for (0..Dv) |dvi| {
                for (0..Dk) |dki| st_out[((b * Hv + hv) * Dv + dvi) * Dk + dki] = @floatCast(S[dvi * Dk + dki]);
            }
        }
    }
    return .{ .y = y, .state = st_out };
}

const GdnRunOut = struct { y: mlx.mlx_array, state: mlx.mlx_array };

/// Run the GDN recurrence via the stock single-state kernel (blocked=false)
/// or the blocked-seq prefill kernel (blocked=true) and return BOTH outputs.
fn gdnRunYState(blocked: bool, tb_requested: u32, q: mlx.mlx_array, k: mlx.mlx_array, v: mlx.mlx_array, g: mlx.mlx_array, beta: mlx.mlx_array, state_in: mlx.mlx_array, B: c_int, T: c_int, Hk: c_int, Hv: c_int, Dk: c_int, Dv: c_int, s: mlx.mlx_stream) !GdnRunOut {
    // Mirror the production route exactly: dtypes read off the arrays, block
    // size clamped to what the staging budget allows at that width.
    const in_dtype = mlx.mlx_array_dtype(q);
    const st_dtype = mlx.mlx_array_dtype(state_in);
    const tb = gdnBlockTFor(tb_requested, Dk, mlx.mlx_array_itemsize(q)) orelse return error.GdnBlockedDeclined;
    const T_scalar = mlx.mlx_array_new_int(T);
    defer _ = mlx.mlx_array_free(T_scalar);
    const y_shape = [_]c_int{ B, T, Hv, Dv };
    const so_shape = [_]c_int{ B, Hv, Dv, Dk };
    const config = mlx.mlx_fast_metal_kernel_config_new();
    defer _ = mlx.mlx_fast_metal_kernel_config_free(config);
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_output_arg(config, &y_shape, 4, .bfloat16));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_output_arg(config, &so_shape, 4, .bfloat16));
    if (blocked) {
        try mlx.check(mlx.mlx_fast_metal_kernel_config_set_grid(config, 256 * @divExact(Dv, 32), Hv, B));
        try mlx.check(mlx.mlx_fast_metal_kernel_config_set_thread_group(config, 256, 1, 1));
    } else {
        try mlx.check(mlx.mlx_fast_metal_kernel_config_set_grid(config, 32, Dv, B * Hv));
        try mlx.check(mlx.mlx_fast_metal_kernel_config_set_thread_group(config, 32, 4, 1));
    }
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_dtype(config, "InT", in_dtype));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_dtype(config, "StT", st_dtype));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_dtype(config, "OutT", .bfloat16));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Dk", Dk));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Dv", Dv));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Hk", Hk));
    try mlx.check(mlx.mlx_fast_metal_kernel_config_add_template_arg_int(config, "Hv", Hv));

    const inputs_arr = [_]mlx.mlx_array{ q, k, v, g, beta, state_in, T_scalar };
    const inputs_vec = mlx.mlx_vector_array_new_data(&inputs_arr, inputs_arr.len);
    defer _ = mlx.mlx_vector_array_free(inputs_vec);
    const kern = if (blocked) try getGdnKernelBlocked(tb) else try getGdnKernel(false);
    var outputs_vec = mlx.mlx_vector_array_new();
    defer _ = mlx.mlx_vector_array_free(outputs_vec);
    try mlx.check(mlx.mlx_fast_metal_kernel_apply(&outputs_vec, kern, inputs_vec, config, s));
    if (mlx.mlx_vector_array_size(outputs_vec) != 2) return error.MetalKernelBadOutputCount;
    var yo = mlx.mlx_array_new();
    var so = mlx.mlx_array_new();
    try mlx.check(mlx.mlx_vector_array_get(&yo, outputs_vec, 0));
    try mlx.check(mlx.mlx_vector_array_get(&so, outputs_vec, 1));
    return .{ .y = yo, .state = so };
}

/// Eval an mlx array as f32 and copy its data into a fresh slice.
fn evalToF32(al: std.mem.Allocator, arr: mlx.mlx_array, n: usize, s: mlx.mlx_stream) ![]f32 {
    var f = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(f);
    try mlx.check(mlx.mlx_astype(&f, arr, .float32, s));
    try mlx.check(mlx.mlx_array_eval(f));
    const d = mlx.mlx_array_data_float32(f) orelse return error.InvalidDtype;
    const out = try al.alloc(f32, n);
    @memcpy(out, d[0..n]);
    return out;
}

fn maxAbsDiff(a: []const f32, b: []const f32) f32 {
    var m: f32 = 0;
    for (a, b) |x, y| m = @max(m, @abs(x - y));
    return m;
}

/// `in_dtype` is the ACTIVATION width q/k/v arrive in. bf16 is the common
/// case; an f16 checkpoint promotes its activations to f32 (f16 ⊕ f32 scalar),
/// which is a different kernel specialization AND a different threadgroup
/// budget — both covered by the sweep below.
const GdnCase = struct { B: c_int, T: c_int, Hk: c_int, Hv: c_int, Dv: c_int, tb: u32, in_dtype: mlx.mlx_dtype = .bfloat16 };

/// Runs one geometry through host ref + stock + blocked and asserts the
/// blocked kernel is no less accurate than the stock kernel it replaces.
fn gdnBlockedParityCase(case: GdnCase, s: mlx.mlx_stream) !void {
    const al = testing.allocator;
    const B = case.B;
    const T = case.T;
    const Hk = case.Hk;
    const Hv = case.Hv;
    const Dk: c_int = 128;
    const Dv = case.Dv;
    const qn: usize = @intCast(B * T * Hk * Dk);
    const vn: usize = @intCast(B * T * Hv * Dv);
    const gn: usize = @intCast(B * T * Hv);
    const sn: usize = @intCast(B * Hv * Dv * Dk);

    var prng = std.Random.DefaultPrng.init(0xB10C5ED);
    const rnd = prng.random();
    const qd = try al.alloc(f32, qn);
    defer al.free(qd);
    const kd = try al.alloc(f32, qn);
    defer al.free(kd);
    const vd = try al.alloc(f32, vn);
    defer al.free(vd);
    const gd = try al.alloc(f32, gn);
    defer al.free(gd);
    const bd = try al.alloc(f32, gn);
    defer al.free(bd);
    const sd = try al.alloc(f32, sn);
    defer al.free(sd);
    for (qd) |*x| x.* = bf16Trunc(rnd.float(f32) - 0.5);
    for (kd) |*x| x.* = bf16Trunc(rnd.float(f32) - 0.5);
    for (vd) |*x| x.* = bf16Trunc(rnd.float(f32) - 0.5);
    for (gd) |*x| x.* = bf16Trunc(0.5 + 0.4 * rnd.float(f32));
    for (bd) |*x| x.* = bf16Trunc(rnd.float(f32));
    for (sd) |*x| x.* = bf16Trunc(rnd.float(f32) - 0.5);

    const ref = try gdnHostRef(al, qd, kd, vd, gd, bd, sd, @intCast(B), @intCast(T), @intCast(Hk), @intCast(Hv), @intCast(Dk), @intCast(Dv));
    defer al.free(ref.y);
    defer al.free(ref.state);

    const qsh = [_]c_int{ B, T, Hk, Dk };
    const vsh = [_]c_int{ B, T, Hv, Dv };
    const gsh = [_]c_int{ B, T, Hv };
    const ssh = [_]c_int{ B, Hv, Dv, Dk };
    const q32 = mlx.mlx_array_new_data(qd.ptr, &qsh, 4, .float32);
    defer _ = mlx.mlx_array_free(q32);
    const k32 = mlx.mlx_array_new_data(kd.ptr, &qsh, 4, .float32);
    defer _ = mlx.mlx_array_free(k32);
    const v32 = mlx.mlx_array_new_data(vd.ptr, &vsh, 4, .float32);
    defer _ = mlx.mlx_array_free(v32);
    const g32 = mlx.mlx_array_new_data(gd.ptr, &gsh, 3, .float32);
    defer _ = mlx.mlx_array_free(g32);
    const b32 = mlx.mlx_array_new_data(bd.ptr, &gsh, 3, .float32);
    defer _ = mlx.mlx_array_free(b32);
    const st32 = mlx.mlx_array_new_data(sd.ptr, &ssh, 4, .float32);
    defer _ = mlx.mlx_array_free(st32);

    var q = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q);
    var kk = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(kk);
    var v = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(v);
    var g = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(g);
    var beta = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(beta);
    var st = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(st);
    // Mirrors the live dtype signature: q/k/v/beta follow the ACTIVATION width
    // (bf16 checkpoints stay bf16; f16 checkpoints promote to f32), `g` is
    // always bf16 because it comes out of our fused gate kernel, and the SSM
    // state buffer is always bf16 because we allocate it that way. The mixed
    // set is the point — the kernel must read each input at its own width.
    try mlx.check(mlx.mlx_astype(&q, q32, case.in_dtype, s));
    try mlx.check(mlx.mlx_astype(&kk, k32, case.in_dtype, s));
    try mlx.check(mlx.mlx_astype(&v, v32, case.in_dtype, s));
    try mlx.check(mlx.mlx_astype(&g, g32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&beta, b32, case.in_dtype, s));
    try mlx.check(mlx.mlx_astype(&st, st32, .bfloat16, s));

    const stock = try gdnRunYState(false, 16, q, kk, v, g, beta, st, B, T, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(stock.y);
    defer _ = mlx.mlx_array_free(stock.state);
    const blocked = try gdnRunYState(true, case.tb, q, kk, v, g, beta, st, B, T, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(blocked.y);
    defer _ = mlx.mlx_array_free(blocked.state);

    const stock_y = try evalToF32(al, stock.y, vn, s);
    defer al.free(stock_y);
    const stock_st = try evalToF32(al, stock.state, sn, s);
    defer al.free(stock_st);
    const blk_y = try evalToF32(al, blocked.y, vn, s);
    defer al.free(blk_y);
    const blk_st = try evalToF32(al, blocked.state, sn, s);
    defer al.free(blk_st);

    // No-worse-than-reference: the blocked kernel's error vs the f64 ground
    // truth must not exceed the stock kernel's (both bf16-out; 1.5x headroom
    // covers fp32 summation-order differences, gross bugs blow way past it).
    const stock_y_err = maxAbsDiff(stock_y, ref.y);
    const stock_st_err = maxAbsDiff(stock_st, ref.state);
    const blk_y_err = maxAbsDiff(blk_y, ref.y);
    const blk_st_err = maxAbsDiff(blk_st, ref.state);
    if (blk_y_err > 1.5 * stock_y_err + 0.02 or blk_st_err > 1.5 * stock_st_err + 0.02) {
        std.debug.print(
            "GDN blocked parity FAIL (B={d} T={d} Hk={d} Hv={d} Dv={d} tb={d}): y {d:.5} vs stock {d:.5}, state {d:.5} vs stock {d:.5}\n",
            .{ case.B, case.T, case.Hk, case.Hv, case.Dv, case.tb, blk_y_err, stock_y_err, blk_st_err, stock_st_err },
        );
        return error.GdnBlockedParityFailed;
    }
}

test "GDN blocked-seq kernel: no worse than stock vs f64 ground truth (T/GQA/Dv/TB sweep)" {
    const s = mlx.gpuStream();
    // T deliberately hits non-multiples of every supported TB (16/32/48);
    // Hk<Hv exercises GQA head mapping; Dv 32..128 exercises 1..4 DB blocks.
    const cases = [_]GdnCase{
        .{ .B = 1, .T = 100, .Hk = 2, .Hv = 4, .Dv = 128, .tb = 32 }, // live-like 27B geometry (fewer heads)
        .{ .B = 2, .T = 64, .Hk = 1, .Hv = 2, .Dv = 32, .tb = 32 }, // batch>1, minimal Dv
        .{ .B = 1, .T = 65, .Hk = 1, .Hv = 2, .Dv = 64, .tb = 16 }, // TB=16 variant, ragged tail 1
        .{ .B = 1, .T = 49, .Hk = 2, .Hv = 2, .Dv = 32, .tb = 48 }, // TB=48 variant, ragged tail 1
        // fp32 activations (f16 checkpoints promote to them — the geometry
        // that killed the server on prism-ml/Ternary-Bonsai-27B-mlx-2bit).
        // The kernel must specialize on the real width AND clamp the block
        // size to fit the doubled staging; requesting 32/48 exercises both.
        .{ .B = 1, .T = 100, .Hk = 2, .Hv = 4, .Dv = 128, .tb = 32, .in_dtype = .float32 },
        .{ .B = 1, .T = 49, .Hk = 2, .Hv = 2, .Dv = 32, .tb = 48, .in_dtype = .float32 },
        .{ .B = 2, .T = 64, .Hk = 1, .Hv = 2, .Dv = 64, .tb = 16, .in_dtype = .float32 },
        // f16 activations: same 2-byte staging as bf16, different kernel.
        .{ .B = 1, .T = 100, .Hk = 2, .Hv = 4, .Dv = 64, .tb = 32, .in_dtype = .float16 },
    };
    for (cases) |case| try gdnBlockedParityCase(case, s);
}

test "GDN blocked-seq kernel: chunk-boundary state continuity (split run == full run)" {
    const s = mlx.gpuStream();
    const al = testing.allocator;
    const B: c_int = 1;
    const T: c_int = 100;
    const T1: c_int = 48; // non-multiple of TB=32: exercises the ragged tail mid-sequence
    const Hk: c_int = 2;
    const Hv: c_int = 4;
    const Dk: c_int = 128;
    const Dv: c_int = 64;
    const qn: usize = @intCast(B * T * Hk * Dk);
    const vn: usize = @intCast(B * T * Hv * Dv);
    const gn: usize = @intCast(B * T * Hv);
    const sn: usize = @intCast(B * Hv * Dv * Dk);

    var prng = std.Random.DefaultPrng.init(0x5EC0DD);
    const rnd = prng.random();
    const qd = try al.alloc(f32, qn);
    defer al.free(qd);
    const kd = try al.alloc(f32, qn);
    defer al.free(kd);
    const vd = try al.alloc(f32, vn);
    defer al.free(vd);
    const gd = try al.alloc(f32, gn);
    defer al.free(gd);
    const bd = try al.alloc(f32, gn);
    defer al.free(bd);
    const sd = try al.alloc(f32, sn);
    defer al.free(sd);
    for (qd) |*x| x.* = bf16Trunc(rnd.float(f32) - 0.5);
    for (kd) |*x| x.* = bf16Trunc(rnd.float(f32) - 0.5);
    for (vd) |*x| x.* = bf16Trunc(rnd.float(f32) - 0.5);
    for (gd) |*x| x.* = bf16Trunc(0.5 + 0.4 * rnd.float(f32));
    for (bd) |*x| x.* = bf16Trunc(rnd.float(f32));
    for (sd) |*x| x.* = bf16Trunc(rnd.float(f32) - 0.5);

    const qsh = [_]c_int{ B, T, Hk, Dk };
    const vsh = [_]c_int{ B, T, Hv, Dv };
    const gsh = [_]c_int{ B, T, Hv };
    const ssh = [_]c_int{ B, Hv, Dv, Dk };
    const q32 = mlx.mlx_array_new_data(qd.ptr, &qsh, 4, .float32);
    defer _ = mlx.mlx_array_free(q32);
    const k32 = mlx.mlx_array_new_data(kd.ptr, &qsh, 4, .float32);
    defer _ = mlx.mlx_array_free(k32);
    const v32 = mlx.mlx_array_new_data(vd.ptr, &vsh, 4, .float32);
    defer _ = mlx.mlx_array_free(v32);
    const g32 = mlx.mlx_array_new_data(gd.ptr, &gsh, 3, .float32);
    defer _ = mlx.mlx_array_free(g32);
    const b32 = mlx.mlx_array_new_data(bd.ptr, &gsh, 3, .float32);
    defer _ = mlx.mlx_array_free(b32);
    const st32 = mlx.mlx_array_new_data(sd.ptr, &ssh, 4, .float32);
    defer _ = mlx.mlx_array_free(st32);

    var q = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q);
    var kk = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(kk);
    var v = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(v);
    var g = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(g);
    var beta = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(beta);
    var st = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(st);
    try mlx.check(mlx.mlx_astype(&q, q32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&kk, k32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&v, v32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&g, g32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&beta, b32, .bfloat16, s));
    try mlx.check(mlx.mlx_astype(&st, st32, .bfloat16, s));

    // Full run.
    const full = try gdnRunYState(true, 32, q, kk, v, g, beta, st, B, T, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(full.y);
    defer _ = mlx.mlx_array_free(full.state);

    // Split run: [0, T1) then [T1, T), carrying the bf16 state — exactly what
    // chunked prefill does (ssm_state hand-off between forwardWith chunks).
    const strides4 = [_]c_int{ 1, 1, 1, 1 };
    const strides3 = [_]c_int{ 1, 1, 1 };
    var q1 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q1);
    var k1 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(k1);
    var v1 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(v1);
    var g1 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(g1);
    var b1 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(b1);
    try mlx.check(mlx.mlx_slice(&q1, q, &[_]c_int{ 0, 0, 0, 0 }, 4, &[_]c_int{ B, T1, Hk, Dk }, 4, &strides4, 4, s));
    try mlx.check(mlx.mlx_slice(&k1, kk, &[_]c_int{ 0, 0, 0, 0 }, 4, &[_]c_int{ B, T1, Hk, Dk }, 4, &strides4, 4, s));
    try mlx.check(mlx.mlx_slice(&v1, v, &[_]c_int{ 0, 0, 0, 0 }, 4, &[_]c_int{ B, T1, Hv, Dv }, 4, &strides4, 4, s));
    try mlx.check(mlx.mlx_slice(&g1, g, &[_]c_int{ 0, 0, 0 }, 3, &[_]c_int{ B, T1, Hv }, 3, &strides3, 3, s));
    try mlx.check(mlx.mlx_slice(&b1, beta, &[_]c_int{ 0, 0, 0 }, 3, &[_]c_int{ B, T1, Hv }, 3, &strides3, 3, s));
    var q2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(q2);
    var k2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(k2);
    var v2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(v2);
    var g2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(g2);
    var b2 = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(b2);
    try mlx.check(mlx.mlx_slice(&q2, q, &[_]c_int{ 0, T1, 0, 0 }, 4, &[_]c_int{ B, T, Hk, Dk }, 4, &strides4, 4, s));
    try mlx.check(mlx.mlx_slice(&k2, kk, &[_]c_int{ 0, T1, 0, 0 }, 4, &[_]c_int{ B, T, Hk, Dk }, 4, &strides4, 4, s));
    try mlx.check(mlx.mlx_slice(&v2, v, &[_]c_int{ 0, T1, 0, 0 }, 4, &[_]c_int{ B, T, Hv, Dv }, 4, &strides4, 4, s));
    try mlx.check(mlx.mlx_slice(&g2, g, &[_]c_int{ 0, T1, 0 }, 3, &[_]c_int{ B, T, Hv }, 3, &strides3, 3, s));
    try mlx.check(mlx.mlx_slice(&b2, beta, &[_]c_int{ 0, T1, 0 }, 3, &[_]c_int{ B, T, Hv }, 3, &strides3, 3, s));

    const part1 = try gdnRunYState(true, 32, q1, k1, v1, g1, b1, st, B, T1, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(part1.y);
    defer _ = mlx.mlx_array_free(part1.state);
    const part2 = try gdnRunYState(true, 32, q2, k2, v2, g2, b2, part1.state, B, T - T1, Hk, Hv, Dk, Dv, s);
    defer _ = mlx.mlx_array_free(part2.y);
    defer _ = mlx.mlx_array_free(part2.state);

    const full_st = try evalToF32(al, full.state, sn, s);
    defer al.free(full_st);
    const split_st = try evalToF32(al, part2.state, sn, s);
    defer al.free(split_st);

    // The only divergence allowed is the one bf16 state rounding injected at
    // the boundary (live chunked prefill injects the identical rounding).
    var max_mag: f32 = 0;
    for (full_st) |x| max_mag = @max(max_mag, @abs(x));
    const tol = 0.02 * max_mag + 0.02;
    const st_diff = maxAbsDiff(full_st, split_st);
    try testing.expect(st_diff < tol);

    // y of the second chunk must also line up with the full run's tail.
    var y_tail = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(y_tail);
    try mlx.check(mlx.mlx_slice(&y_tail, full.y, &[_]c_int{ 0, T1, 0, 0 }, 4, &[_]c_int{ B, T, Hv, Dv }, 4, &strides4, 4, s));
    const n2: usize = @intCast(B * (T - T1) * Hv * Dv);
    const tail_f = try evalToF32(al, y_tail, n2, s);
    defer al.free(tail_f);
    const part2_y = try evalToF32(al, part2.y, n2, s);
    defer al.free(part2_y);
    try testing.expect(maxAbsDiff(tail_f, part2_y) < tol);
}

test "gdnBlockTFor: the block size follows the INPUT WIDTH, not a bf16 assumption" {
    // bf16/f16 stage 2 bytes — every supported block size fits, so the
    // requested one stands.
    try testing.expectEqual(@as(?u32, 16), gdnBlockTFor(16, 128, 2));
    try testing.expectEqual(@as(?u32, 32), gdnBlockTFor(32, 128, 2));
    try testing.expectEqual(@as(?u32, 48), gdnBlockTFor(48, 128, 2));

    // fp32 activations (what an f16 checkpoint promotes to) stage 4 bytes:
    // TB=32 needs ~40 KiB and TB=48 ~60 KiB, both past Metal's 32 KiB
    // threadgroup budget, so each clamps DOWN rather than emitting a kernel
    // that fails to compile and takes the server with it.
    try testing.expectEqual(@as(?u32, 16), gdnBlockTFor(16, 128, 4));
    try testing.expectEqual(@as(?u32, 16), gdnBlockTFor(32, 128, 4));
    try testing.expectEqual(@as(?u32, 16), gdnBlockTFor(48, 128, 4));

    // The staging budget the clamp is derived from — pinned so a change to
    // the kernel's threadgroup declarations has to come here too.
    try testing.expect(gdnBlockedTgBytes(48, 128, 2) <= METAL_TG_BYTES);
    try testing.expect(gdnBlockedTgBytes(16, 128, 4) <= METAL_TG_BYTES);
    try testing.expect(gdnBlockedTgBytes(32, 128, 4) > METAL_TG_BYTES);

    // Nothing fits at all → decline the blocked route (null), never fall
    // through to an over-budget dispatch.
    try testing.expectEqual(@as(?u32, null), gdnBlockTFor(48, 128, 16));
    // A request below the smallest supported block declines too.
    try testing.expectEqual(@as(?u32, null), gdnBlockTFor(8, 128, 2));
}

test "gdnBlockedEligible: width floor + exact-128 Dk + Dv/head-group alignment" {
    // Live 27B GDN geometry at prefill width: eligible.
    try testing.expect(gdnBlockedEligible(2048, 128, 128, 16, 32));
    try testing.expect(gdnBlockedEligible(GDN_BLOCKED_MIN_T, 128, 128, 16, 32));
    // Below the width floor (decode, spec verify widths): stock kernel.
    try testing.expect(!gdnBlockedEligible(GDN_BLOCKED_MIN_T - 1, 128, 128, 16, 32));
    try testing.expect(!gdnBlockedEligible(1, 128, 128, 16, 32));
    // Off-geometry: Dk != 128, Dv not a multiple of 32, ragged GQA grouping.
    try testing.expect(!gdnBlockedEligible(2048, 96, 128, 16, 32));
    try testing.expect(!gdnBlockedEligible(2048, 256, 128, 16, 32));
    try testing.expect(!gdnBlockedEligible(2048, 128, 48, 16, 32));
    try testing.expect(!gdnBlockedEligible(2048, 128, 16, 16, 32));
    try testing.expect(!gdnBlockedEligible(2048, 128, 128, 3, 32));
}

/// Assert a verify-kernel output is NO LESS ACCURATE than the stock qmm it
/// replaces, both measured against `wdq_t` — the SAME 4-bit weights dequantized
/// to fp32 (so quantization error cancels and only the two kernels' own
/// arithmetic is under test).
///
/// This is the machine-independent invariant. A direct kernel-vs-stock bound is
/// NOT: both paths accumulate fp32 in a different order and round to bf16, so on
/// heavily-cancelling data each already sits ~0.03 from truth on its worst
/// element and they may legitimately differ from each other by more than that.
/// Tuning a pair-agreement threshold on one GPU produces a test that is green on
/// the dev machine and red on the CI runner while the kernel is bit-for-bit as
/// accurate (measured: kernel-vs-truth == stock-vs-truth to four decimals).
/// A genuine defect — a partial-sum race, a register spill, bad indexing —
/// pushes kernel-vs-truth far past stock-vs-truth and is still caught here.
/// Parity bars for a verify lane, stated so that no bar is fit per GPU.
///
/// A per-chip max-error slack was tried first (M1 Pro measured kern_max 0.0313
/// against stock 0.0039 while cosine stayed at 0.999998, so the bar was
/// widened to 0.04 there). That is the wrong shape of guard twice over:
///
///   - Widening the MAX blinds the test to what it exists to catch. Cosine is
///     a GLOBAL measure, so a partial-sum race, a register spill or a bad
///     index — one element far off, everything else intact — passes a widened
///     max with cosine unmoved.
///   - `stock_max` is not a stable reference. The same shapes measure
///     stock_max 0.02-0.035 on M4 Max, so the M1 Pro row was not a lane
///     landing 8x worse than normal, it was STOCK landing unusually well
///     there. Anything keyed to stock's worst element inherits that.
///
/// So neither bar references stock's max any more:
///
///   - `GROSS_CEILING` is an ABSOLUTE ceiling on the worst element. On the
///     clamped-relative metric below, a bf16 output's own rounding noise sits
///     at 0.02-0.035 on every machine measured; a corrupted accumulator lands
///     orders of magnitude past 0.5. This is the single-element bar.
///   - `RMS_FACTOR` bounds the whole error distribution against stock's,
///     which is scale-free: when stock is unusually accurate the ratio is
///     what stays meaningful. This is the systematic bar. (M1 Pro's cosines
///     imply a ratio near 1.4; M4 Max measures 1.00 across every lane.)
///   - The cosine bars are unchanged and catch a broken reference.
const VerifyQmmParity = struct {
    /// Absolute ceiling on the worst element's clamped relative error.
    const GROSS_CEILING: f64 = 0.5;
    /// How much of stock's RMS error the lane may carry.
    const RMS_FACTOR: f64 = 3.0;
    /// Cosine may not fall below stock's by more than this.
    const COS_SLACK: f64 = 1e-5;
    /// …and both must actually be tracking the truth.
    const COS_FLOOR: f64 = 0.999;
};

/// Why a verify-lane parity check failed, or null when it passed. Pure so the
/// decision itself is unit-testable without a GPU — each arm is a distinct
/// failure shape the bars are meant to separate.
const VerifyQmmParityFail = enum { gross_element, systematic, cosine, not_tracking };

fn verifyQmmParityVerdict(
    kern_max: f64,
    rms_stock: f64,
    rms_kern: f64,
    cos_stock: f64,
    cos_kern: f64,
) ?VerifyQmmParityFail {
    if (cos_kern < VerifyQmmParity.COS_FLOOR) return .not_tracking;
    if (cos_kern < cos_stock - VerifyQmmParity.COS_SLACK) return .cosine;
    if (kern_max > VerifyQmmParity.GROSS_CEILING) return .gross_element;
    // A zero stock RMS means the reference is exact on this data; the ratio
    // then demands the lane be exact too, which is the strictest reading and
    // the one we want — an exactly-representable case a lane cannot reproduce
    // is a defect, not reduction-order noise.
    if (rms_kern > VerifyQmmParity.RMS_FACTOR * rms_stock) return .systematic;
    return null;
}

fn expectVerifyQmmNoWorseThanStock(
    s: mlx.mlx_stream,
    x: mlx.mlx_array,
    wq: mlx.mlx_array,
    wsc: mlx.mlx_array,
    wbi: mlx.mlx_array,
    bits: u32,
    gs: u32,
    wdq_t: mlx.mlx_array,
    got: mlx.mlx_array,
    label: []const u8,
) !void {
    var ref = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(ref);
    try mlx.check(mlx.mlx_quantized_matmul(&ref, x, wq, wsc, wbi, true, mlx.mlx_optional_int.some(@intCast(gs)), mlx.mlx_optional_int.some(@intCast(bits)), "affine", s));

    var xf = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(xf);
    try mlx.check(mlx.mlx_astype(&xf, x, .float32, s));
    var truth = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(truth);
    try mlx.check(mlx.mlx_matmul(&truth, xf, wdq_t, s));

    var tf = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(tf);
    var rf = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(rf);
    var gf = mlx.mlx_array_new();
    defer _ = mlx.mlx_array_free(gf);
    try mlx.check(mlx.mlx_astype(&tf, truth, .float32, s));
    try mlx.check(mlx.mlx_astype(&rf, ref, .float32, s));
    try mlx.check(mlx.mlx_astype(&gf, got, .float32, s));
    try mlx.check(mlx.mlx_array_eval(tf));
    try mlx.check(mlx.mlx_array_eval(rf));
    try mlx.check(mlx.mlx_array_eval(gf));
    const td = mlx.mlx_array_data_float32(tf).?;
    const rd = mlx.mlx_array_data_float32(rf).?;
    const gd = mlx.mlx_array_data_float32(gf).?;

    const gsh = mlx.getShape(got);
    const count: usize = @intCast(gsh[1] * gsh[2]);
    var stock_max: f64 = 0;
    var kern_max: f64 = 0;
    var dot_s: f64 = 0;
    var dot_k: f64 = 0;
    var nt: f64 = 0;
    var ns: f64 = 0;
    var nk: f64 = 0;
    // First pass: cosines against the fp32 truth, plus each side's worst
    // element. Neither max is a BAR any more (see VerifyQmmParity) — stock's
    // is reported alongside the kernel's so a failure line shows both.
    for (0..count) |i| {
        const t: f64 = td[i];
        const r: f64 = rd[i];
        const g: f64 = gd[i];
        // Clamped denominator: a near-zero output of a heavily-cancelling dot
        // product must not manufacture a huge ratio from a tiny absolute error.
        const denom = @max(1.0, @abs(t));
        stock_max = @max(stock_max, @abs(r - t) / denom);
        kern_max = @max(kern_max, @abs(g - t) / denom);
        dot_s += r * t;
        dot_k += g * t;
        nt += t * t;
        ns += r * r;
        nk += g * g;
    }
    var se_s: f64 = 0;
    var se_k: f64 = 0;
    for (0..count) |i| {
        const t: f64 = td[i];
        const denom = @max(1.0, @abs(t));
        const es = (@as(f64, rd[i]) - t) / denom;
        const ek = (@as(f64, gd[i]) - t) / denom;
        se_s += es * es;
        se_k += ek * ek;
    }
    const n_f: f64 = @floatFromInt(count);
    const rms_stock = @sqrt(se_s / n_f);
    const rms_kern = @sqrt(se_k / n_f);
    const cos_stock = dot_s / (@sqrt(ns) * @sqrt(nt));
    const cos_kern = dot_k / (@sqrt(nk) * @sqrt(nt));

    if (std.c.getenv("MLX_SERVE_VQMM_PARITY_DEBUG") != null) {
        std.debug.print(
            "[vqmm-parity] {s:>16}: n={d} max {d:.5}/{d:.5} rms {d:.6}/{d:.6} (ratio {d:.3}) cos {d:.7}/{d:.7}\n",
            .{ label, count, stock_max, kern_max, rms_stock, rms_kern, if (rms_stock > 0) rms_kern / rms_stock else 0, cos_stock, cos_kern },
        );
    }

    if (verifyQmmParityVerdict(kern_max, rms_stock, rms_kern, cos_stock, cos_kern)) |why| {
        std.debug.print(
            "verifyQmm parity FAIL [{s}] ({s}): n={d} kernel max={d:.4} rms={d:.6} cos={d:.6}; " ++
                "stock max={d:.4} rms={d:.6} cos={d:.6}; bars: max<={d:.2} rms<={d:.1}x cos>=stock-{d}\n",
            .{
                label,                      @tagName(why),
                count,                      kern_max,
                rms_kern,                   cos_kern,
                stock_max,                  rms_stock,
                cos_stock,                  VerifyQmmParity.GROSS_CEILING,
                VerifyQmmParity.RMS_FACTOR, VerifyQmmParity.COS_SLACK,
            },
        );
        return error.TestExpectedApproxEq;
    }
}

test "verifyQmmParityVerdict: reduction-order noise passes, a gross or systematic error does not" {
    // Reduction-order noise: a worse worst-element than stock, cosine intact.
    // This is the M1 Pro measurement (kern_max 0.0313 while stock landed an
    // unusually good 0.0039 at cos 0.999998) and it must PASS with no
    // per-chip bar — the max is no longer judged against stock's at all.
    try testing.expect(verifyQmmParityVerdict(0.0313, 0.0009, 0.0013, 0.999999, 0.999998) == null);
    // M4 Max: every shipped lane measures ratio 1.00.
    try testing.expect(verifyQmmParityVerdict(0.0308, 0.0012, 0.0012, 0.999998, 0.999998) == null);
    // One accumulator corrupted: a single element, rms and cosine still fine
    // — the exact shape a max-slack widened to 0.04 would have waved through.
    try testing.expectEqual(
        VerifyQmmParityFail.gross_element,
        verifyQmmParityVerdict(12.0, 0.0012, 0.0013, 0.999999, 0.999997).?,
    );
    // Systematically noisier without a single gross element: rms is the bar
    // that sees it, and it is scale-free so an accurate stock cannot hide it.
    try testing.expectEqual(
        VerifyQmmParityFail.systematic,
        verifyQmmParityVerdict(0.4, 0.0009, 0.0040, 0.999999, 0.999995).?,
    );
    try testing.expectEqual(
        VerifyQmmParityFail.cosine,
        verifyQmmParityVerdict(0.005, 0.0012, 0.0012, 0.999999, 0.99990).?,
    );
    try testing.expectEqual(
        VerifyQmmParityFail.not_tracking,
        verifyQmmParityVerdict(0.005, 0.0012, 0.0012, 0.5, 0.4).?,
    );
    // A lane BETTER than stock is never a failure.
    try testing.expect(verifyQmmParityVerdict(0.0001, 0.0012, 0.0002, 0.999998, 0.999999) == null);
}

test "verifyQmm: the plain-SIMD tiles match stock qmm at 5/6/8-bit affine too" {
    // The split-K and msg tiles were 4-bit specializations by construction, so
    // every non-4-bit pack fell through to stock on the whole M1-M4 line — the
    // Qwen3.8-27B 6-bit pack (95.0% top-1 against bf16 vs the 4-bit pack's
    // 83.6%) paid the full lane-off penalty on every MTP round. The byte-
    // addressed unpack lifted from the NAX m16 tile fixes that; this pins it.
    //
    // Same bar as the 4-bit test: no worse than stock against an fp32 dequant
    // reference, never kernel-vs-kernel. Parity is asserted independently of
    // the PROFITABILITY predicate — `vqmm_mixed_plain_test_force` opens the
    // gate so a shape the measurement later declines is still proven correct.
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0xB175);
    const rnd = prng.random();

    vqmm_mixed_plain_test_force = true;
    defer vqmm_mixed_plain_test_force = null;
    // The NAX probe must not steal these rows on an M5 box: this test is about
    // the plain-SIMD lanes, and M 2..7 is below the NAX takeover anyway.
    vqmm_nax_probe_override = false;
    defer vqmm_nax_probe_override = null;

    const cases = [_]struct { k: c_int, n: c_int, gs: u32, label: []const u8 }{
        .{ .k = 5120, .n = 17408, .gs = 64, .label = "mlp" }, // MLP gate/up, split-K
        .{ .k = 2048, .n = 151936, .gs = 64, .label = "lm_head" }, // huge N, msg tile
        // The unpack is independent of the group size (gs only indexes the
        // scale/bias pair), but the forced-on A/B arm adopts every gs, so the
        // other two are proven rather than argued.
        .{ .k = 2048, .n = 5120, .gs = 32, .label = "gs32" },
        .{ .k = 2048, .n = 5120, .gs = 128, .label = "gs128" },
    };
    for ([_]u32{ 5, 6, 8 }) |bits| {
        for (cases) |cs| {
            const wn: usize = @intCast(cs.n * cs.k);
            const wbuf = try allocator.alloc(f32, wn);
            defer allocator.free(wbuf);
            for (wbuf) |*v| v.* = rnd.float(f32) - 0.5;
            const wshape = [_]c_int{ cs.n, cs.k };
            const w32 = mlx.mlx_array_new_data(wbuf.ptr, &wshape, 2, .float32);
            defer _ = mlx.mlx_array_free(w32);
            var wb = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wb);
            try mlx.check(mlx.mlx_astype(&wb, w32, .bfloat16, s));

            var triple = mlx.mlx_vector_array_new();
            defer _ = mlx.mlx_vector_array_free(triple);
            try mlx.check(mlx.mlx_quantize(&triple, wb, mlx.mlx_optional_int.some(@intCast(cs.gs)), mlx.mlx_optional_int.some(@intCast(bits)), "affine", .{}, s));
            var wq = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wq);
            var wsc = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wsc);
            var wbi = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wbi);
            try mlx.check(mlx.mlx_vector_array_get(&wq, triple, 0));
            try mlx.check(mlx.mlx_vector_array_get(&wsc, triple, 1));
            try mlx.check(mlx.mlx_vector_array_get(&wbi, triple, 2));

            var wdq = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wdq);
            try mlx.check(mlx.mlx_dequantize(&wdq, wq, wsc, wbi, mlx.mlx_optional_int.some(@intCast(cs.gs)), mlx.mlx_optional_int.some(@intCast(bits)), "affine", .{ .ctx = null }, mlx.mlx_optional_dtype{ .has_value = true, .value = .float32 }, s));
            var wdq_t = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wdq_t);
            const t_axes = [_]c_int{ 1, 0 };
            try mlx.check(mlx.mlx_transpose_axes(&wdq_t, wdq, &t_axes, 2, s));

            for ([_]c_int{ 2, 4, 7 }) |m| {
                const xn: usize = @intCast(m * cs.k);
                const xbuf = try allocator.alloc(f32, xn);
                defer allocator.free(xbuf);
                for (xbuf) |*v| v.* = rnd.float(f32) - 0.5;
                const xshape = [_]c_int{ 1, m, cs.k };
                const x32 = mlx.mlx_array_new_data(xbuf.ptr, &xshape, 3, .float32);
                defer _ = mlx.mlx_array_free(x32);
                var x = mlx.mlx_array_new();
                defer _ = mlx.mlx_array_free(x);
                try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));

                const got_opt = try verifyQmm(s, x, wq, wsc, wbi, bits, cs.gs);
                try testing.expect(got_opt != null);
                const got = got_opt.?;
                defer _ = mlx.mlx_array_free(got);
                const gsh = mlx.getShape(got);
                try testing.expectEqual(m, gsh[1]);
                try testing.expectEqual(cs.n, gsh[2]);
                try expectVerifyQmmNoWorseThanStock(s, x, wq, wsc, wbi, bits, cs.gs, wdq_t, got, cs.label);
            }

            // With the gate closed the same shape falls through to stock — the
            // profitability predicate is what decides adoption, and a lane that
            // cannot be declined is a lane that cannot be A/B'd.
            {
                vqmm_mixed_plain_test_force = false;
                defer vqmm_mixed_plain_test_force = true;
                const xbuf = try allocator.alloc(f32, @intCast(4 * cs.k));
                defer allocator.free(xbuf);
                for (xbuf) |*v| v.* = 0.1;
                const xshape = [_]c_int{ 1, 4, cs.k };
                const x32 = mlx.mlx_array_new_data(xbuf.ptr, &xshape, 3, .float32);
                defer _ = mlx.mlx_array_free(x32);
                var x = mlx.mlx_array_new();
                defer _ = mlx.mlx_array_free(x);
                try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));
                try testing.expectEqual(@as(?mlx.mlx_array, null), try verifyQmm(s, x, wq, wsc, wbi, bits, cs.gs));
            }
        }
    }
}

test "mixedPlainShapeEnabled: adoption is what was MEASURED, per width and per shape" {
    const t = testing;
    // 4-bit is the original specialization and is always in.
    try t.expect(mixedPlainShapeEnabled(4, 64, 1024));

    // 6-bit is the measured win (1.10-1.22x on the Qwen3.8-27B 6-bit pack).
    try t.expect(mixedPlainShapeEnabled(6, 64, MIXED_PLAIN_MIN_N));
    try t.expect(mixedPlainShapeEnabled(6, 64, 17408));
    // Narrow projections (GDN ba, K/V) are where the byte-addressed unpack
    // loses to stock — the same shape-dependence mixedNaxShapeEnabled encodes,
    // and forcing them on gave back ~10 of the ~20 points.
    try t.expect(!mixedPlainShapeEnabled(6, 64, MIXED_PLAIN_MIN_N - 1));
    try t.expect(!mixedPlainShapeEnabled(6, 64, 1024));
    // Only gs 64 was measured.
    try t.expect(!mixedPlainShapeEnabled(6, 32, 17408));
    try t.expect(!mixedPlainShapeEnabled(6, 128, 17408));

    // 8-bit HAS a correct kernel arm and a parity test, and is still default
    // OFF: measured 1.01-1.04x, inside what this harness resolves. 5-bit has
    // the arm too but no pack on the measuring box, so it does not get to ride
    // 6-bit's number. Both are one env var from on — an unmeasured default is
    // the thing this predicate exists to prevent.
    for ([_]u32{ 5, 8 }) |b| {
        try t.expect(!mixedPlainShapeEnabled(b, 64, 17408));
    }
    // A width with no unpack arm is never adopted, whatever the shape.
    for ([_]u32{ 2, 3, 7 }) |b| try t.expect(!mixedPlainShapeEnabled(b, 64, 17408));
}

test "verifyQmm: split-K + msg + NAX verify-width kernels match stock qmm (4-bit affine)" {
    // The spec-verify fast path: stock MLX qmm is tuned for M=1 (qmv) and
    // large M (steel); the 2..8-row verify shapes fall in a dead zone.
    // Port of MTPLX's split-K verify kernel family (verify_kernels.py,
    // Apache-2.0) — parity vs mlx_quantized_matmul at real 27B shapes.
    //
    // THE INVARIANT IS "NO LESS ACCURATE THAN STOCK", NOT "AGREES WITH STOCK".
    // Both paths accumulate in fp32 in a DIFFERENT ORDER and then round the
    // result to bf16, so the two outputs legitimately disagree by a few ULPs —
    // and on this data (K=5120 dot products of U(-0.5,0.5) → heavy cancellation)
    // each path already sits up to ~0.036 from the true value on its worst
    // element, purely from that bf16 output rounding. A direct kernel-vs-stock
    // bound therefore pins AGREEMENT tighter than bf16 permits: the original
    // `max_rel <= 0.02` / `cos > 0.99999` thresholds were tuned on one GPU and
    // the CI runner's GPU (different rounding, same correctness) failed them at
    // max_rel 0.0977 / cos 0.999988 — a green-here/red-there test that says
    // nothing about correctness. Measured: kernel-vs-truth equals stock-vs-truth
    // to four decimals on every shape.
    //
    // So both paths are measured against an fp32 DEQUANT REFERENCE (the same
    // 4-bit weights, dequantized, matmul'd in fp32 — the ground truth both are
    // approximating) and the kernel must be no worse than the stock kernel it
    // replaces. That is machine-independent, and a real defect (a partial-sum
    // race, a register spill, bad indexing) blows kernel-vs-truth far past
    // stock-vs-truth while a rounding-order difference cannot.
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0x5EED);
    const rnd = prng.random();

    const cases = [_]struct { k: c_int, n: c_int, gs: u32 }{
        .{ .k = 5120, .n = 17408, .gs = 64 }, // MLP gate/up
        .{ .k = 5120, .n = 1024, .gs = 32 }, // small-N above the gate, MTP gs-32 class
        .{ .k = 2048, .n = 5120, .gs = 128 }, // gs-128 arm
    };
    for (cases) |cs| {
        // Random dense weight → 4-bit affine triple.
        const wn: usize = @intCast(cs.n * cs.k);
        const wbuf = try allocator.alloc(f32, wn);
        defer allocator.free(wbuf);
        for (wbuf) |*v| v.* = rnd.float(f32) - 0.5;
        const wshape = [_]c_int{ cs.n, cs.k };
        const w32 = mlx.mlx_array_new_data(wbuf.ptr, &wshape, 2, .float32);
        defer _ = mlx.mlx_array_free(w32);
        var wb = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wb);
        try mlx.check(mlx.mlx_astype(&wb, w32, .bfloat16, s));
        var triple = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(triple);
        try mlx.check(mlx.mlx_quantize(&triple, wb, mlx.mlx_optional_int.some(@intCast(cs.gs)), mlx.mlx_optional_int.some(4), "affine", .{}, s));
        var wq = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wq);
        var wsc = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wsc);
        var wbi = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wbi);
        try mlx.check(mlx.mlx_vector_array_get(&wq, triple, 0));
        try mlx.check(mlx.mlx_vector_array_get(&wsc, triple, 1));
        try mlx.check(mlx.mlx_vector_array_get(&wbi, triple, 2));

        // fp32 ground truth operand: the same 4-bit weights, dequantized.
        var wdq = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wdq);
        try mlx.check(mlx.mlx_dequantize(&wdq, wq, wsc, wbi, mlx.mlx_optional_int.some(@intCast(cs.gs)), mlx.mlx_optional_int.some(4), "affine", .{ .ctx = null }, mlx.mlx_optional_dtype{ .has_value = true, .value = .float32 }, s));
        var wdq_t = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wdq_t);
        const t_axes = [_]c_int{ 1, 0 };
        try mlx.check(mlx.mlx_transpose_axes(&wdq_t, wdq, &t_axes, 2, s));

        // Kernel rows: split-K M 2..7 on every machine; the NAX m16 tile rows
        // (M 8..16, the padding path at 8/9/12 and the exact-16 tile) run only
        // where the M5-class probe is live (todo-m5-nax.md §9.3) — the probe
        // self-gates, so plain-SIMD machines skip them.
        const simd_ms = [_]c_int{ 2, 3, 4, 5, 6, 7 };
        const nax_ms = [_]c_int{ 8, 9, 12, 16 };
        const total_ms: usize = if (verifyQmmNaxEnabled()) simd_ms.len + nax_ms.len else simd_ms.len;
        var mi: usize = 0;
        while (mi < total_ms) : (mi += 1) {
            const m = if (mi < simd_ms.len) simd_ms[mi] else nax_ms[mi - simd_ms.len];
            const label: []const u8 = if (mi < simd_ms.len) "split-K" else "nax m16";
            const xn: usize = @intCast(m * cs.k);
            const xbuf = try allocator.alloc(f32, xn);
            defer allocator.free(xbuf);
            for (xbuf) |*v| v.* = rnd.float(f32) - 0.5;
            const xshape = [_]c_int{ 1, m, cs.k };
            const x32 = mlx.mlx_array_new_data(xbuf.ptr, &xshape, 3, .float32);
            defer _ = mlx.mlx_array_free(x32);
            var x = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(x);
            try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));

            // Kernel path — must ENGAGE for every listed M, at EVERY column
            // tile the sweep can force. `MLX_SERVE_VQMM_BN` is an A/B lever,
            // so a tile that silently computed the wrong thing would only
            // show up mid-measurement; null forces the shipped per-M default.
            for ([_]?c_int{null} ++ [_]?c_int{ 2, 4, 8 }) |bn_force| {
                if (bn_force) |bn| {
                    // The NAX tile ignores bn; only the split-K rows sweep.
                    if (mi >= simd_ms.len) continue;
                    if (@mod(cs.n, bn) != 0 or bn * m > VQMM_MAX_ACC) continue;
                }
                vqmm_bn_test_override = bn_force;
                defer vqmm_bn_test_override = null;
                const got_opt = try verifyQmm(s, x, wq, wsc, wbi, 4, cs.gs);
                try testing.expect(got_opt != null);
                const got = got_opt.?;
                defer _ = mlx.mlx_array_free(got);
                const gsh = mlx.getShape(got);
                try testing.expectEqual(@as(c_int, 1), gsh[0]);
                try testing.expectEqual(m, gsh[1]);
                try testing.expectEqual(cs.n, gsh[2]);

                try expectVerifyQmmNoWorseThanStock(s, x, wq, wsc, wbi, 4, cs.gs, wdq_t, got, label);
            }
        }

        // Ineligible widths fall through to stock (null). The NAX probe is
        // FORCED false so this pins the plain-SIMD (M1-M4) dispatch on every
        // machine, an M5 running the suite included: M=1 stays qmv, M 8..16
        // must NOT reach the split-K family (the measured spill cliff past 7
        // live row vectors), and M=17 is past every lane.
        {
            vqmm_nax_probe_override = false;
            defer vqmm_nax_probe_override = null;
            for ([_]c_int{ 1, 8, 16, 17 }) |bad_m| {
                const xn: usize = @intCast(bad_m * cs.k);
                const xbuf = try allocator.alloc(f32, xn);
                defer allocator.free(xbuf);
                for (xbuf) |*v| v.* = 0.1;
                const xshape = [_]c_int{ 1, bad_m, cs.k };
                const x32 = mlx.mlx_array_new_data(xbuf.ptr, &xshape, 3, .float32);
                defer _ = mlx.mlx_array_free(x32);
                var x = mlx.mlx_array_new();
                defer _ = mlx.mlx_array_free(x);
                try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));
                try testing.expectEqual(@as(?mlx.mlx_array, null), try verifyQmm(s, x, wq, wsc, wbi, 4, cs.gs));
            }
        }

        // M=1 stays stock under the REAL probe too (MTPLX's tile nominally
        // covers M 1..16, but M=1 belongs to stock qmv on every machine).
        {
            const xbuf = try allocator.alloc(f32, @intCast(cs.k));
            defer allocator.free(xbuf);
            for (xbuf) |*v| v.* = 0.1;
            const xshape = [_]c_int{ 1, 1, cs.k };
            const x32 = mlx.mlx_array_new_data(xbuf.ptr, &xshape, 3, .float32);
            defer _ = mlx.mlx_array_free(x32);
            var x = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(x);
            try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));
            try testing.expectEqual(@as(?mlx.mlx_array, null), try verifyQmm(s, x, wq, wsc, wbi, 4, cs.gs));
        }
    }

    // Mixed-precision trunk projections: the M5 NAX lane adopts affine
    // 5/6/8-bit weights on the measured wide shape class. Keep this self-gated
    // like the NAX rows above so non-G17 CI never attempts to compile an
    // unavailable MPP kernel.
    if (verifyQmmNaxEnabled()) {
        const k: c_int = 512;
        const n: c_int = 5120;
        const gs: u32 = 64;
        for ([_]u32{ 5, 6, 8 }) |bits| {
            const wn: usize = @intCast(n * k);
            const wbuf = try allocator.alloc(f32, wn);
            defer allocator.free(wbuf);
            for (wbuf) |*v| v.* = rnd.float(f32) - 0.5;
            const wshape = [_]c_int{ n, k };
            const w32 = mlx.mlx_array_new_data(wbuf.ptr, &wshape, 2, .float32);
            defer _ = mlx.mlx_array_free(w32);
            var wb = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wb);
            try mlx.check(mlx.mlx_astype(&wb, w32, .bfloat16, s));

            var triple = mlx.mlx_vector_array_new();
            defer _ = mlx.mlx_vector_array_free(triple);
            try mlx.check(mlx.mlx_quantize(
                &triple,
                wb,
                mlx.mlx_optional_int.some(@intCast(gs)),
                mlx.mlx_optional_int.some(@intCast(bits)),
                "affine",
                .{},
                s,
            ));
            var wq = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wq);
            var wsc = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wsc);
            var wbi = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wbi);
            try mlx.check(mlx.mlx_vector_array_get(&wq, triple, 0));
            try mlx.check(mlx.mlx_vector_array_get(&wsc, triple, 1));
            try mlx.check(mlx.mlx_vector_array_get(&wbi, triple, 2));

            var wdq = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wdq);
            try mlx.check(mlx.mlx_dequantize(
                &wdq,
                wq,
                wsc,
                wbi,
                mlx.mlx_optional_int.some(@intCast(gs)),
                mlx.mlx_optional_int.some(@intCast(bits)),
                "affine",
                .{ .ctx = null },
                mlx.mlx_optional_dtype{ .has_value = true, .value = .float32 },
                s,
            ));
            var wdq_t = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wdq_t);
            const t_axes = [_]c_int{ 1, 0 };
            try mlx.check(mlx.mlx_transpose_axes(&wdq_t, wdq, &t_axes, 2, s));

            const m: c_int = 8;
            const xn: usize = @intCast(m * k);
            const xbuf = try allocator.alloc(f32, xn);
            defer allocator.free(xbuf);
            for (xbuf) |*v| v.* = rnd.float(f32) - 0.5;
            const xshape = [_]c_int{ 1, m, k };
            const x32 = mlx.mlx_array_new_data(xbuf.ptr, &xshape, 3, .float32);
            defer _ = mlx.mlx_array_free(x32);
            var x = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(x);
            try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));

            const got_opt = try verifyQmm(s, x, wq, wsc, wbi, bits, gs);
            try testing.expect(got_opt != null);
            const got = got_opt.?;
            defer _ = mlx.mlx_array_free(got);
            try expectVerifyQmmNoWorseThanStock(
                s,
                x,
                wq,
                wsc,
                wbi,
                bits,
                gs,
                wdq_t,
                got,
                switch (bits) {
                    5 => "nax oQe q5",
                    6 => "nax oQe q6",
                    else => "nax q8 candidate",
                },
            );

            // Below the NAX takeover row, default adoption remains the measured
            // width/shape surface: this q6/gs64/N=5120 projection uses the
            // plain-SIMD lane, while q5 still falls through to stock.
            const x6buf = try allocator.alloc(f32, 6 * @as(usize, @intCast(k)));
            defer allocator.free(x6buf);
            for (x6buf) |*v| v.* = 0.1;
            const x6shape = [_]c_int{ 1, 6, k };
            const x6f = mlx.mlx_array_new_data(x6buf.ptr, &x6shape, 3, .float32);
            defer _ = mlx.mlx_array_free(x6f);
            var x6 = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(x6);
            try mlx.check(mlx.mlx_astype(&x6, x6f, .bfloat16, s));
            const got6_opt = try verifyQmm(s, x6, wq, wsc, wbi, bits, gs);
            if (bits == 6) {
                try testing.expect(got6_opt != null);
                const got6 = got6_opt.?;
                defer _ = mlx.mlx_array_free(got6);
                try expectVerifyQmmNoWorseThanStock(s, x6, wq, wsc, wbi, bits, gs, wdq_t, got6, "plain-SIMD q6");
            } else {
                try testing.expectEqual(@as(?mlx.mlx_array, null), got6_opt);
            }
        }
    }

    // ── msg wide-tile parity (the huge-N/lm_head arm), called directly with
    // a RAGGED N (1000 % 32 != 0) so the in-kernel n0 guard is exercised. ──
    {
        const mk: c_int = 2048;
        const mn: c_int = 1000;
        const wn: usize = @intCast(mn * mk);
        const wbuf = try allocator.alloc(f32, wn);
        defer allocator.free(wbuf);
        for (wbuf) |*v| v.* = rnd.float(f32) - 0.5;
        const wshape = [_]c_int{ mn, mk };
        const w32 = mlx.mlx_array_new_data(wbuf.ptr, &wshape, 2, .float32);
        defer _ = mlx.mlx_array_free(w32);
        var wb = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wb);
        try mlx.check(mlx.mlx_astype(&wb, w32, .bfloat16, s));
        var triple = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(triple);
        try mlx.check(mlx.mlx_quantize(&triple, wb, mlx.mlx_optional_int.some(64), mlx.mlx_optional_int.some(4), "affine", .{}, s));
        var wq = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wq);
        var wsc = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wsc);
        var wbi = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wbi);
        try mlx.check(mlx.mlx_vector_array_get(&wq, triple, 0));
        try mlx.check(mlx.mlx_vector_array_get(&wsc, triple, 1));
        try mlx.check(mlx.mlx_vector_array_get(&wbi, triple, 2));

        var wdq = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wdq);
        try mlx.check(mlx.mlx_dequantize(&wdq, wq, wsc, wbi, mlx.mlx_optional_int.some(64), mlx.mlx_optional_int.some(4), "affine", .{ .ctx = null }, mlx.mlx_optional_dtype{ .has_value = true, .value = .float32 }, s));
        var wdq_t = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wdq_t);
        const t_axes = [_]c_int{ 1, 0 };
        try mlx.check(mlx.mlx_transpose_axes(&wdq_t, wdq, &t_axes, 2, s));

        var m: c_int = 2;
        while (m <= 6) : (m += 1) {
            const xn: usize = @intCast(m * mk);
            const xbuf = try allocator.alloc(f32, xn);
            defer allocator.free(xbuf);
            for (xbuf) |*v| v.* = rnd.float(f32) - 0.5;
            const xshape = [_]c_int{ 1, m, mk };
            const x32 = mlx.mlx_array_new_data(xbuf.ptr, &xshape, 3, .float32);
            defer _ = mlx.mlx_array_free(x32);
            var x = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(x);
            try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));

            const xsh = mlx.getShape(x);
            const got = (try runVerifyQmmMsg(s, x, wq, wsc, wbi, 4, 64, m, mk, mn, .bfloat16, xsh)).?;
            defer _ = mlx.mlx_array_free(got);

            try expectVerifyQmmNoWorseThanStock(s, x, wq, wsc, wbi, 4, 64, wdq_t, got, "msg ragged-N");
        }
    }
}

test "vqmmLaneFor: NAX dispatch table (M 8..16 route to the m16 tile only when the probe is live)" {
    // Pure lane selection — todo-m5-nax.md §7. Hermetic on every machine:
    // no kernels are built, only the routing decision is pinned.
    const nax_off = false;
    const nax_on = true;

    // Plain-SIMD machine (probe false): the table is byte-identical to the
    // pre-NAX dispatch — M 8..16 fall through to stock.
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(1, 5120, 17408, nax_off, 8, false));
    try testing.expectEqual(VqmmLane.splitk, vqmmLaneFor(2, 5120, 17408, nax_off, 8, false));
    try testing.expectEqual(VqmmLane.splitk, vqmmLaneFor(7, 5120, 17408, nax_off, 8, false));
    try testing.expectEqual(VqmmLane.msg, vqmmLaneFor(4, 5120, 151936, nax_off, 8, false));
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(8, 5120, 17408, nax_off, 8, false));
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(16, 5120, 17408, nax_off, 8, false));
    // Geometry floors shared by every lane.
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(4, 5120, 256, nax_off, 8, false)); // N < 512
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(4, 100, 17408, nax_off, 8, false)); // K % 64 != 0
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(4, 5120, 17409, nax_off, 8, false)); // N % 4 != 0

    // M5 (probe true), default takeover width 8: M 2..7 KEEP the plain-SIMD
    // lanes (MTPLX's own dispatcher keeps SIMD through M=6 with NAX lit —
    // 16-row padding waste makes SIMD competitive at small M).
    try testing.expectEqual(VqmmLane.splitk, vqmmLaneFor(7, 5120, 17408, nax_on, 8, false));
    try testing.expectEqual(VqmmLane.msg, vqmmLaneFor(7, 5120, 151936, nax_on, 8, false));
    // M 8..16 route to the NAX tile when its stricter geometry holds…
    try testing.expectEqual(VqmmLane.nax, vqmmLaneFor(8, 5120, 17408, nax_on, 8, false));
    try testing.expectEqual(VqmmLane.nax, vqmmLaneFor(16, 5120, 17408, nax_on, 8, false));
    // …including the lm_head class natively (N=151936 % 32 == 0 — no msg
    // variant needed past M=7).
    try testing.expectEqual(VqmmLane.nax, vqmmLaneFor(9, 5120, 151936, nax_on, 8, false));
    // Tile-ineligible geometry at M 8..16 stays stock: K % 256, N % 32.
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(8, 5184, 17408, nax_on, 8, false)); // 5184 % 256 == 64
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(8, 5120, 17412, nax_on, 8, false)); // 17412 % 32 == 4
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(17, 5120, 17408, nax_on, 8, false)); // past every lane
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(1, 5120, 17408, nax_on, 8, false)); // M=1 stays qmv
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(8, 5120, 480, nax_on, 8, false)); // tiny-N floor holds for NAX too

    // The M5-day A/B knob (MLX_SERVE_VERIFY_QMM_NAX_MIN_M=5): M 5..7 route
    // to NAX, M 4 keeps split-K, and the tile geometry is still required —
    // a lowered width never bypasses it, it falls back to the SIMD lanes.
    try testing.expectEqual(VqmmLane.nax, vqmmLaneFor(5, 5120, 17408, nax_on, 5, false));
    try testing.expectEqual(VqmmLane.nax, vqmmLaneFor(7, 5120, 151936, nax_on, 5, false));
    try testing.expectEqual(VqmmLane.splitk, vqmmLaneFor(4, 5120, 17408, nax_on, 5, false));
    try testing.expectEqual(VqmmLane.splitk, vqmmLaneFor(5, 5184, 17408, nax_on, 5, false)); // K % 256 fails, % 64 holds

    // Crossrow (opt-in): M 8..9 on plain-SIMD machines at its own geometry
    // (K % 512, N % 8, N >= 1024); NAX outranks it, 2..7 stays split-K, and
    // with the opt-in off the M 8..16 fall-through is unchanged.
    try testing.expectEqual(VqmmLane.crossrow, vqmmLaneFor(8, 5120, 17408, nax_off, 8, true));
    try testing.expectEqual(VqmmLane.crossrow, vqmmLaneFor(9, 5120, 17408, nax_off, 8, true));
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(10, 5120, 17408, nax_off, 8, true)); // past the pair tile
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(8, 5184, 17408, nax_off, 8, true)); // K % 512 != 0
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(8, 5120, 17412, nax_off, 8, true)); // N % 8 != 0
    try testing.expectEqual(VqmmLane.none, vqmmLaneFor(8, 5120, 1016, nax_off, 8, true)); // their host gate: N >= 1024
    try testing.expectEqual(VqmmLane.nax, vqmmLaneFor(8, 5120, 17408, nax_on, 8, true)); // NAX outranks
    try testing.expectEqual(VqmmLane.splitk, vqmmLaneFor(7, 5120, 17408, nax_off, 8, true));
}

test "verifyQmm: crossrow M 8/9 lane matches stock qmm (4-bit g64, opt-in)" {
    // Same bar as the split-K/msg/NAX parity test: no worse than stock
    // against the fp32 dequant ground truth (reduction order differs, so
    // agreement-with-stock is not the bar — the verify-lane rule).
    const s = mlx.gpuStream();
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0xC805);
    const rnd = prng.random();

    vqmm_crossrow_override = true;
    defer vqmm_crossrow_override = null;
    vqmm_nax_probe_override = false; // pin the plain-SIMD dispatch on an M5 too
    defer vqmm_nax_probe_override = null;

    const cases = [_]struct { k: c_int, n: c_int }{
        .{ .k = 5120, .n = 2048 }, // trunk-projection class
        .{ .k = 1536, .n = 17408 }, // MLP-width class, K = 3 x 512
    };
    for (cases) |cs| {
        const wn: usize = @intCast(cs.n * cs.k);
        const wbuf = try allocator.alloc(f32, wn);
        defer allocator.free(wbuf);
        for (wbuf) |*v| v.* = rnd.float(f32) - 0.5;
        const wshape = [_]c_int{ cs.n, cs.k };
        const w32 = mlx.mlx_array_new_data(wbuf.ptr, &wshape, 2, .float32);
        defer _ = mlx.mlx_array_free(w32);
        var wb = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wb);
        try mlx.check(mlx.mlx_astype(&wb, w32, .bfloat16, s));
        var triple = mlx.mlx_vector_array_new();
        defer _ = mlx.mlx_vector_array_free(triple);
        try mlx.check(mlx.mlx_quantize(&triple, wb, mlx.mlx_optional_int.some(64), mlx.mlx_optional_int.some(4), "affine", .{}, s));
        var wq = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wq);
        var wsc = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wsc);
        var wbi = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wbi);
        try mlx.check(mlx.mlx_vector_array_get(&wq, triple, 0));
        try mlx.check(mlx.mlx_vector_array_get(&wsc, triple, 1));
        try mlx.check(mlx.mlx_vector_array_get(&wbi, triple, 2));

        var wdq = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wdq);
        try mlx.check(mlx.mlx_dequantize(&wdq, wq, wsc, wbi, mlx.mlx_optional_int.some(64), mlx.mlx_optional_int.some(4), "affine", .{ .ctx = null }, mlx.mlx_optional_dtype{ .has_value = true, .value = .float32 }, s));
        var wdq_t = mlx.mlx_array_new();
        defer _ = mlx.mlx_array_free(wdq_t);
        const t_axes = [_]c_int{ 1, 0 };
        try mlx.check(mlx.mlx_transpose_axes(&wdq_t, wdq, &t_axes, 2, s));

        // M=8 exercises the all-pairs path, M=9 the zeroed-tail single arm.
        for ([_]c_int{ 8, 9 }) |m| {
            const xn: usize = @intCast(m * cs.k);
            const xbuf = try allocator.alloc(f32, xn);
            defer allocator.free(xbuf);
            for (xbuf) |*v| v.* = rnd.float(f32) - 0.5;
            const xshape = [_]c_int{ 1, m, cs.k };
            const x32 = mlx.mlx_array_new_data(xbuf.ptr, &xshape, 3, .float32);
            defer _ = mlx.mlx_array_free(x32);
            var x = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(x);
            try mlx.check(mlx.mlx_astype(&x, x32, .bfloat16, s));

            const got = (try verifyQmm(s, x, wq, wsc, wbi, 4, 64)) orelse return error.CrossrowDeclined;
            defer _ = mlx.mlx_array_free(got);
            const gsh = mlx.getShape(got);
            try testing.expectEqual(@as(c_int, 1), gsh[0]);
            try testing.expectEqual(m, gsh[1]);
            try testing.expectEqual(cs.n, gsh[2]);
            try expectVerifyQmmNoWorseThanStock(s, x, wq, wsc, wbi, 4, 64, wdq_t, got, "crossrow");
        }

        // gs 32 must not enter the 4/g64 specialization even with the
        // opt-in on (falls to stock = null at these M).
        {
            var t32 = mlx.mlx_vector_array_new();
            defer _ = mlx.mlx_vector_array_free(t32);
            try mlx.check(mlx.mlx_quantize(&t32, wb, mlx.mlx_optional_int.some(32), mlx.mlx_optional_int.some(4), "affine", .{}, s));
            var wq32 = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wq32);
            var ws32 = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(ws32);
            var wb32 = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(wb32);
            try mlx.check(mlx.mlx_vector_array_get(&wq32, t32, 0));
            try mlx.check(mlx.mlx_vector_array_get(&ws32, t32, 1));
            try mlx.check(mlx.mlx_vector_array_get(&wb32, t32, 2));
            const xbuf = try allocator.alloc(f32, @intCast(8 * cs.k));
            defer allocator.free(xbuf);
            for (xbuf) |*v| v.* = 0.1;
            const xshape = [_]c_int{ 1, 8, cs.k };
            const x32b = mlx.mlx_array_new_data(xbuf.ptr, &xshape, 3, .float32);
            defer _ = mlx.mlx_array_free(x32b);
            var x8 = mlx.mlx_array_new();
            defer _ = mlx.mlx_array_free(x8);
            try mlx.check(mlx.mlx_astype(&x8, x32b, .bfloat16, s));
            try testing.expectEqual(@as(?mlx.mlx_array, null), try verifyQmm(s, x8, wq32, ws32, wb32, 4, 32));
        }
    }
}

