        .weight_present = true,
        .packed_weight = true,
        .scales_present = true,
        .biases_present = true,
        .quant = .{ .bits = 4, .group_size = 64, .mode = .affine },
        .K = 5120,
        .N = 248320,
        .packed_k = 640,
        .verify_on = true,
        .lane_on = true,
        .available = true,
        .min_m = 8,
    };
